// Biblioteca Jurídica Práctica SIGDE. Material de consulta general; verificar siempre la norma vigente y el expediente.
export const TERMINOS_PROCESALES = [
{t:'Promoción',d:'Escrito presentado por una parte para formular una petición o impulsar una actuación dentro de un procedimiento.',cuando:'Cuando se necesita solicitar una actuación concreta: copias, reconocimiento de personalidad, cumplimiento de un acuerdo, exhibición de documentos u otra petición procedente.',por:'Permite dejar constancia formal de la solicitud y obtener una determinación del órgano competente.',cuida:'Identifica expediente y partes; formula una petición clara; agrega anexos y firma cuando corresponda. No existe un formato universal para toda promoción.'},
{t:'Demanda',d:'Escrito inicial por el que se somete una pretensión a conocimiento de un órgano jurisdiccional.',cuando:'Al iniciar una vía judicial procedente, una vez revisados competencia, vía, legitimación y requisitos.',por:'Delimita quién reclama, contra quién, qué pide y en qué hechos y fundamentos apoya su pretensión.',cuida:'Precisar prestaciones, hechos numerados, pruebas, documentos, domicilios y requisitos del ordenamiento aplicable.'},
{t:'Prevención',d:'Requerimiento para aclarar, corregir o completar una solicitud o demanda cuando la ley lo permite o exige.',cuando:'Al recibir una resolución que señale defectos u omisiones subsanables.',por:'Busca que se cumplan requisitos antes de que el procedimiento continúe o se decida sobre la admisión.',cuida:'Leer cada punto, identificar notificación y regla de cómputo, responder punto por punto y no suponer que todos los plazos son iguales.'},
{t:'Contestación de demanda',d:'Escrito en el que la parte demandada responde a las pretensiones y hechos planteados en la demanda.',cuando:'Después de un emplazamiento válido y dentro del plazo aplicable.',por:'Fija la postura frente a cada hecho y prestación y permite plantear defensas y excepciones.',cuida:'No responder de forma genérica; verificar consecuencias legales del silencio, ofrecer pruebas y formular reconvención solo si procede.'},
{t:'Emplazamiento',d:'Acto procesal por el que se hace saber formalmente a la parte demandada la existencia del juicio y se le llama a comparecer.',cuando:'Al inicio del procedimiento, conforme a la vía y reglas de notificación aplicables.',por:'Permite conocer la demanda y ejercer defensa dentro del plazo legal.',cuida:'Revisar domicilio, persona con quien se entendió, documentos entregados y constancias; los defectos pueden requerir impugnación o análisis específico.'},
{t:'Notificación',d:'Comunicación procesal de una resolución o actuación a quien legalmente debe conocerla.',cuando:'Cada vez que una resolución deba hacerse del conocimiento de una parte o tercero.',por:'Puede iniciar plazos, permitir cumplimiento o garantizar conocimiento de una decisión.',cuida:'Confirmar medio, fecha y efectos legales; la fecha de lectura no siempre equivale a la fecha jurídica de notificación.'},
{t:'Acuerdo judicial',d:'Determinación emitida por el órgano jurisdiccional para proveer sobre promociones o cuestiones de trámite.',cuando:'Al atender el tribunal una petición o dar curso al procedimiento.',por:'Indica qué se admite, requiere, ordena o tiene por presentado.',cuida:'Leer la parte resolutiva completa, identificar cargas impuestas y plazos; no confundir todo acuerdo con una sentencia definitiva.'},
{t:'Auto',d:'Resolución judicial que decide una cuestión procesal o de trámite con los alcances previstos por la ley.',cuando:'Cuando el tribunal resuelve admisión, medidas, incidentes u otras cuestiones procesales.',por:'Ordena el curso del procedimiento o decide una cuestión específica.',cuida:'La clasificación y los recursos procedentes dependen del código y del contenido de la resolución.'},
{t:'Sentencia',d:'Resolución jurisdiccional que decide las cuestiones sometidas a decisión, de manera definitiva o en los términos que establezca la ley.',cuando:'Al concluir una etapa decisoria o resolver una controversia según el procedimiento.',por:'Define derechos, obligaciones o consecuencias jurídicas controvertidas.',cuida:'Revisar puntos resolutivos, congruencia, fundamentación, notificación y medio de impugnación con su plazo.'},
{t:'Incidente',d:'Cuestión accesoria surgida dentro de un procedimiento que requiere una decisión específica.',cuando:'Cuando se presenta una cuestión que la legislación permite tramitar incidentalmente, como nulidad de actuaciones en supuestos procedentes.',por:'Permite resolver un tema accesorio sin confundirlo con la pretensión principal.',cuida:'Verificar si existe trámite incidental, oportunidad, pruebas y efectos; no toda controversia se tramita como incidente.'},
{t:'Excepción',d:'Defensa mediante la cual la parte demandada controvierte la procedencia de la pretensión o plantea una circunstancia que impide, modifica o extingue sus efectos.',cuando:'Al contestar la demanda o en el momento que disponga la legislación aplicable.',por:'Delimita las razones jurídicas por las que la reclamación no debe prosperar total o parcialmente.',cuida:'Distinguir excepciones procesales y de fondo según el ordenamiento; no basta con etiquetarlas, deben sustentarse en hechos y norma.'},
{t:'Reconvención',d:'Pretensión que la parte demandada formula contra la parte actora dentro del mismo juicio cuando la ley lo permite.',cuando:'En la oportunidad y con los requisitos establecidos para la vía concreta.',por:'Busca que también se resuelva una pretensión propia relacionada con la controversia.',cuida:'Revisar competencia, conexidad, requisitos formales y plazo; no está disponible en todos los procedimientos.'},
{t:'Ofrecimiento de pruebas',d:'Acto por el que una parte propone los medios probatorios con los que pretende acreditar sus afirmaciones.',cuando:'En la etapa y plazo fijados por el procedimiento aplicable.',por:'Vincula hechos controvertidos con medios que pueden demostrarlos.',cuida:'Relacionar cada prueba con hechos concretos, cumplir requisitos y explicar qué se pretende acreditar.'},
{t:'Admisión de pruebas',d:'Determinación judicial sobre qué medios probatorios pueden incorporarse al procedimiento.',cuando:'Después del ofrecimiento y revisión de requisitos, pertinencia y reglas de admisibilidad.',por:'Define qué pruebas serán desahogadas o consideradas conforme a la ley.',cuida:'Revisar exclusiones y recursos que pudieran proceder; ofrecer una prueba no significa que haya sido admitida.'},
{t:'Desahogo de pruebas',d:'Práctica o incorporación procesal del medio probatorio conforme a sus reglas.',cuando:'En audiencia o en la etapa prevista para cada tipo de prueba.',por:'Permite que la prueba se produzca y pueda valorarse legalmente.',cuida:'Preparar testigos, peritos, documentos y objeciones con anticipación; cumplir citaciones y formalidades.'},
{t:'Alegatos',d:'Argumentos finales de las partes sobre los hechos acreditados, las pruebas y el derecho aplicable.',cuando:'En la oportunidad prevista por el procedimiento, frecuentemente al cierre de la etapa probatoria.',por:'Explica cómo las pruebas sostienen la pretensión o defensa y qué decisión se solicita.',cuida:'No sustituir prueba faltante con afirmaciones; vincular argumentos con constancias y puntos controvertidos.'},
{t:'Recurso',d:'Medio de impugnación previsto en la ley para solicitar la revisión de una resolución.',cuando:'Cuando existe una resolución impugnable y se reúnen los requisitos y plazo legales.',por:'Busca que la autoridad competente confirme, modifique o revoque la decisión en los términos permitidos.',cuida:'Identificar resolución, legitimación, agravios, autoridad y plazo; no todas las resoluciones admiten el mismo recurso.'},
{t:'Agravios',d:'Razonamientos que explican por qué una resolución causa perjuicio jurídico y en qué consiste el error impugnado.',cuando:'Al interponer el medio de impugnación que requiera agravios.',por:'Delimitan los errores que se pide revisar.',cuida:'Señalar la consideración combatida, el error, la afectación y la consecuencia solicitada; evitar inconformidades vagas.'},
{t:'Preclusión',d:'Pérdida de la oportunidad procesal para realizar un acto por haber vencido la etapa o plazo, o por otras causas reconocidas legalmente.',cuando:'Al evaluar si un acto todavía puede realizarse dentro del procedimiento.',por:'Protege el orden de las etapas procesales y la certeza del trámite.',cuida:'Verificar norma, notificación, cómputo, suspensiones y excepciones antes de concluir que una oportunidad se perdió.'},
{t:'Caducidad de la instancia',d:'Terminación del procedimiento por inactividad durante el periodo y bajo las condiciones que determine la ley aplicable.',cuando:'Cuando se analiza una posible consecuencia de la inactividad procesal.',por:'Evita que ciertos procedimientos permanezcan indefinidamente sin impulso.',cuida:'Los plazos, materias excluidas, actos interruptivos y efectos varían por ordenamiento; no confundirla con prescripción.'},
{t:'Prescripción',d:'Institución por la que el transcurso del tiempo puede producir adquisición o extinción de derechos o acciones en los supuestos legales.',cuando:'Al evaluar temporalidad de una pretensión, obligación o defensa.',por:'Permite determinar si la reclamación sigue siendo jurídicamente exigible o si se actualizó una consecuencia legal.',cuida:'Identificar acción, plazo especial, inicio del cómputo, interrupción, suspensión y régimen transitorio.'},
{t:'Desistimiento',d:'Manifestación de abandonar una actuación, instancia o pretensión con los efectos que establezca la ley y el caso.',cuando:'Cuando una parte decide no continuar, tras evaluar sus consecuencias.',por:'Puede terminar una actuación o procedimiento, según qué se abandone y los requisitos aplicables.',cuida:'Distinguir desistimiento de la instancia y de la acción; revisar consentimiento, derechos de terceros y efectos.'},
{t:'Convenio judicial',d:'Acuerdo entre partes sometido a aprobación o reconocimiento judicial cuando el procedimiento lo requiere.',cuando:'Cuando existe una solución negociada y la materia permite disponer de los derechos involucrados.',por:'Puede resolver la controversia y establecer obligaciones exigibles.',cuida:'Verificar capacidad, consentimiento, legalidad, derechos indisponibles, precisión de obligaciones y mecanismo de cumplimiento.'},
{t:'Ejecución de sentencia',d:'Etapa o procedimiento destinado a obtener el cumplimiento de una resolución ejecutable.',cuando:'Cuando la resolución puede ejecutarse y la parte obligada no cumple voluntariamente.',por:'Busca materializar lo reconocido judicialmente.',cuida:'Confirmar firmeza o ejecutabilidad, alcance de los puntos resolutivos, plazo y medidas permitidas.'},
{t:'Medida cautelar',d:'Medida provisional prevista por la ley para proteger la eficacia del proceso o evitar un riesgo jurídicamente relevante.',cuando:'Cuando se acreditan los presupuestos que el ordenamiento exige para una protección provisional.',por:'Evita que el paso del tiempo vuelva ineficaz la decisión final o cause el riesgo contemplado por la norma.',cuida:'Justificar urgencia, apariencia del derecho y demás requisitos específicos; no todas las materias usan los mismos estándares.'},
{t:'Legitimación',d:'Relación jurídicamente reconocida entre una persona y la pretensión o defensa que plantea.',cuando:'Al revisar quién puede demandar, ser demandado o intervenir en un procedimiento.',por:'Permite comprobar que quien actúa tiene vínculo legal con la cuestión debatida.',cuida:'Distinguir legitimación procesal y en la causa; acreditar representación y calidad jurídica cuando corresponda.'},
{t:'Jurisdicción',d:'Potestad estatal de resolver controversias y ejercer funciones jurisdiccionales conforme al marco jurídico.',cuando:'Al identificar qué órgano puede conocer del asunto.',por:'Ubica la controversia dentro del sistema de impartición de justicia.',cuida:'Distinguir jurisdicción de competencia y revisar materia, territorio, grado y reglas especiales.'},
{t:'Competencia',d:'Distribución legal de los asuntos entre órganos jurisdiccionales según materia, territorio, cuantía, grado u otros criterios.',cuando:'Antes de presentar una demanda y al revisar objeciones procesales.',por:'Permite acudir al órgano legalmente facultado.',cuida:'No inferirla solo por domicilio; comprobar las reglas vigentes de la vía y del caso.'},
{t:'Diligencia',d:'Actuación formal practicada por autoridad, personal judicial o persona habilitada, según el procedimiento.',cuando:'Para ejecutar una notificación, requerimiento, inspección u otra actuación autorizada.',por:'Deja constancia de hechos y actos relevantes para el procedimiento.',cuida:'Revisar orden, formalidades, personas intervinientes, fecha, resultado y acta correspondiente.'},
{t:'Requerimiento judicial',d:'Mandato formal para que una persona haga, entregue, exhiba o se abstenga de algo en los términos de la resolución.',cuando:'Cuando la autoridad lo ordena conforme a sus facultades.',por:'Procura cumplimiento o informa de consecuencias por incumplimiento.',cuida:'Identificar destinatario, obligación, plazo y apercibimiento exacto; no asumir consecuencias no expresadas en la ley o resolución.'}
,
{t:'Audiencia',d:'Acto procesal formal en el que la autoridad escucha a las partes, recibe argumentos o pruebas, intenta conciliación o adopta decisiones, según el procedimiento.',cuando:'Cuando el órgano jurisdiccional la señala o la ley prevé una audiencia para una etapa determinada.',por:'Permite ejercer derechos procesales y realizar actos que deben desarrollarse oralmente o con intervención de las partes.',cuida:'Confirmar objeto, fecha, modalidad, comparecientes, preparación de pruebas, consecuencias de inasistencia y reglas específicas de la materia.'},
{t:'Audiencia inicial',d:'Audiencia que, en determinados procedimientos, concentra actos iniciales como control de la comparecencia, depuración, acuerdos o decisiones preliminares.',cuando:'Solo cuando el procedimiento aplicable contempla esta etapa y se ha señalado legalmente.',por:'Organiza el proceso y permite resolver cuestiones previas.',cuida:'Su contenido cambia entre materias y códigos; consultar la norma aplicable y no trasladar automáticamente reglas de un sistema a otro.'},
{t:'Audiencia preliminar',d:'Audiencia previa al juicio que puede servir para depurar el procedimiento, explorar acuerdos, fijar hechos no controvertidos o admitir pruebas.',cuando:'Cuando la legislación de la vía prevé esta etapa.',por:'Evita controversias innecesarias y prepara la etapa de juicio.',cuida:'Revisar los actos que deben realizarse, acuerdos probatorios, excepciones y consecuencias de no comparecer.'},
{t:'Audiencia de juicio',d:'Audiencia en la que se desahogan pruebas y se exponen argumentos conforme a las reglas del procedimiento.',cuando:'Cuando el asunto llega a la etapa de juicio y se fija fecha.',por:'Permite la producción y contradicción de prueba antes de la decisión.',cuida:'Preparar testigos, peritos, documentos, objeciones y alegatos; confirmar orden y reglas de intervención.'},
{t:'Audiencia de conciliación',d:'Sesión destinada a explorar una solución acordada entre las partes con intervención de la autoridad o persona conciliadora.',cuando:'Cuando la ley la establece o las partes acuden válidamente a un mecanismo conciliatorio.',por:'Puede resolver el conflicto total o parcialmente y reducir tiempo y costos.',cuida:'Verificar si es obligatoria, efectos de inasistencia, facultades de representación y requisitos de validez del convenio.'},
{t:'Sentencia definitiva',d:'Resolución que decide la cuestión principal o pone fin a una instancia en los términos definidos por la legislación aplicable.',cuando:'Al concluir la etapa decisoria del procedimiento.',por:'Determina el resultado judicial de las pretensiones sometidas a decisión.',cuida:'Leer considerandos y puntos resolutivos; revisar notificación, recursos, plazos y si la decisión es ejecutable o ya es firme.'},
{t:'Sentencia interlocutoria',d:'Resolución que decide una cuestión incidental o accesoria en los términos del código aplicable.',cuando:'Cuando se tramita y resuelve un incidente u otra cuestión que legalmente se decida por interlocutoria.',por:'Resuelve una cuestión específica sin necesariamente decidir el fondo de la controversia principal.',cuida:'La denominación y los recursos procedentes varían entre ordenamientos; identificar la norma aplicable y el contenido real de la resolución.'},
{t:'Sentencia firme',d:'Resolución que ya no puede ser modificada mediante los medios ordinarios de impugnación disponibles en el caso, conforme a las reglas aplicables.',cuando:'Cuando vencen los plazos sin impugnación, se agotan los medios procedentes o se actualiza otra causa legal de firmeza.',por:'Aporta estabilidad a lo decidido y puede habilitar efectos de ejecución o cosa juzgada.',cuida:'No confundir notificación, ejecutabilidad provisional y firmeza; verificar recursos pendientes, constancias y declaración judicial cuando corresponda.'},
{t:'Sentencia ejecutoriada',d:'Expresión utilizada para una resolución que ha adquirido firmeza o autoridad de cosa juzgada conforme al régimen aplicable.',cuando:'Cuando se actualizan los supuestos legales para que la resolución cause ejecutoria.',por:'Permite identificar que la decisión quedó jurídicamente consolidada para los efectos previstos por la ley.',cuida:'La forma de declarar la ejecutoria y sus efectos dependen del ordenamiento; revisar expediente y constancia respectiva.'},
{t:'Cosa juzgada',d:'Efecto de estabilidad y vinculación que el ordenamiento atribuye a determinadas decisiones firmes.',cuando:'Al analizar si una controversia ya fue resuelta judicialmente y si una nueva acción coincide jurídicamente con la anterior.',por:'Evita que se vuelva a litigar una cuestión que reúne los requisitos legales de cosa juzgada.',cuida:'Examinar sujetos, objeto, causa, alcance de la resolución y excepciones; no toda decisión firme produce idénticos efectos.'},
{t:'Citación para sentencia',d:'Determinación procesal que indica que el asunto está en estado de resolverse y se remite a decisión, según la vía.',cuando:'Cuando se han cumplido las etapas necesarias para dictar sentencia.',por:'Marca el cierre de la etapa de alegaciones o de actividad previa conforme al código.',cuida:'Registrar fecha y efectos; verificar si todavía procede alguna actuación y cuál es el plazo legal para resolver.'},
{t:'Puntos resolutivos',d:'Apartado final de una resolución que expresa las determinaciones concretas de la autoridad.',cuando:'Al estudiar qué ordenó el tribunal y al ejecutar o impugnar la resolución.',por:'Permite identificar con precisión condenas, absoluciones, declaraciones y mandatos.',cuida:'Leerlos junto con los considerandos; si hay contradicción u omisión, analizar el mecanismo procesal procedente.'},
{t:'Considerandos',d:'Parte argumentativa de una resolución en la que se exponen antecedentes, valoración y razones jurídicas.',cuando:'Al revisar la motivación de una sentencia o preparar su impugnación o cumplimiento.',por:'Explican cómo la autoridad conecta hechos, pruebas y normas con su decisión.',cuida:'Relacionar cada argumento con los puntos resolutivos; identificar omisiones, contradicciones o falta de motivación.'},
{t:'Acuerdo de trámite',d:'Determinación que provee sobre el curso ordinario del procedimiento o una petición, de acuerdo con la terminología del órgano y la ley.',cuando:'Cuando el tribunal recibe una promoción o necesita ordenar una actuación.',por:'Impulsa y organiza el expediente.',cuida:'No asumir que todo acuerdo es impugnable; revisar naturaleza, efectos y régimen de recursos.'},
{t:'Proveído',d:'Término de uso forense para referirse a la determinación que recae a una promoción o asunto.',cuando:'Al describir la respuesta judicial a una petición.',por:'Identifica el acto de proveer o resolver una solicitud.',cuida:'Es una expresión de uso práctico; para determinar efectos jurídicos atender al contenido de la resolución y al código.'},
{t:'Vista',d:'Acto por el que se pone una promoción, documento o cuestión en conocimiento de una parte o autoridad para que manifieste lo que a su derecho convenga, según el caso.',cuando:'Cuando la ley o el tribunal ordena dar vista.',por:'Garantiza conocimiento y oportunidad de pronunciarse.',cuida:'Revisar destinatario, objeto, forma de notificación y plazo; una vista no tiene siempre el mismo término.'},
{t:'Traslado',d:'Comunicación procesal que permite a una parte conocer una promoción o documento y responder en el plazo que corresponda.',cuando:'Cuando se corre traslado de demanda, contestación, incidente u otro escrito.',por:'Hace posible la contradicción y el ejercicio de defensa.',cuida:'Verificar qué documentos se entregaron, cuándo surtió efectos la notificación y el plazo legal.'},
{t:'Apercibimiento',d:'Advertencia formal de la consecuencia que podría producirse si no se cumple una orden o carga procesal.',cuando:'Cuando la autoridad lo incluye en un requerimiento o determinación.',por:'Informa de antemano las consecuencias legalmente previstas del incumplimiento.',cuida:'La consecuencia debe tener sustento legal; no asumir que se actualiza automáticamente sin verificar requisitos.'},
{t:'Rebeldía',d:'Situación procesal atribuida a quien no comparece o no realiza un acto en los términos legales, con efectos que dependen del procedimiento.',cuando:'Cuando una parte incumple una carga de comparecencia o contestación y la ley prevé esa consecuencia.',por:'Permite continuar el procedimiento en las condiciones que establece la norma.',cuida:'No equivale automáticamente a aceptar todos los hechos; revisar régimen de notificaciones, efectos y derechos subsistentes.'},
{t:'Deserción del recurso',d:'Consecuencia procesal por incumplir requisitos necesarios para que un recurso continúe, cuando la ley así lo establece.',cuando:'Al evaluar omisiones del recurrente, como falta de expresión de agravios o incumplimiento de una carga legal.',por:'Puede impedir el examen del recurso.',cuida:'No usar el término sin identificar el recurso, la norma y el incumplimiento concreto; las consecuencias varían.'},
{t:'Improcedencia',d:'Falta de un presupuesto jurídico para que una pretensión, medio de defensa o solicitud sea examinada o concedida.',cuando:'Al analizar requisitos legales antes de estudiar el fondo o al resolver una cuestión procesal.',por:'Permite distinguir defectos de procedencia de una decisión sobre el mérito.',cuida:'Precisar la causa legal; improcedencia no siempre equivale a que el derecho sustantivo no exista.'},
{t:'Desechamiento',d:'Determinación de no admitir una demanda, promoción, prueba o recurso por una causa prevista legalmente.',cuando:'Cuando el órgano identifica un defecto o impedimento que legalmente justifica no admitir el acto.',por:'Evita tramitar actos que no satisfacen los requisitos aplicables.',cuida:'Distinguir desechamiento de prevención, sobreseimiento y sentencia de fondo; revisar motivación y medio de impugnación.'},
{t:'Admisión de demanda',d:'Resolución que acepta tramitar la demanda al estimar satisfechos los requisitos iniciales, sin que ello signifique ganar el juicio.',cuando:'Tras la presentación y revisión inicial del escrito.',por:'Abre el trámite judicial y puede ordenar emplazamiento u otras actuaciones.',cuida:'La admisión no acredita por sí misma los hechos ni garantiza procedencia final; atender las cargas posteriores.'},
{t:'Sobreseimiento',d:'Terminación del procedimiento o de una parte de él sin resolver necesariamente el fondo, por una causa prevista legalmente.',cuando:'Cuando se actualiza un supuesto legal que impide continuar con el examen de fondo.',por:'Concluye el proceso en los alcances que determine la resolución.',cuida:'Revisar causa, materia, efectos, firmeza y si permite presentar otra acción; no equipararlo automáticamente a absolución.'},
{t:'Reposición del procedimiento',d:'Orden de repetir una etapa o actuación procesal afectada por un vicio, en los términos que determine la autoridad competente.',cuando:'Cuando se acredita una irregularidad que legalmente exige reponer actuaciones.',por:'Busca restablecer el debido proceso y corregir el defecto.',cuida:'Identificar qué actos quedan sin efecto, desde qué punto se repone y cuáles deben conservarse.'},
{t:'Nulidad de actuaciones',d:'Planteamiento dirigido a que se declare inválida una actuación procesal por un defecto jurídicamente relevante.',cuando:'Cuando se identifica una irregularidad que cumple los presupuestos de nulidad previstos en el ordenamiento.',por:'Busca corregir actos que afectaron la regularidad del procedimiento o derechos procesales.',cuida:'Analizar oportunidad, trascendencia, convalidación, perjuicio y vía adecuada; no toda irregularidad produce nulidad.'},
{t:'Notificación personal',d:'Modalidad de notificación que la ley reserva para ciertos actos o resoluciones y que exige formalidades específicas.',cuando:'Cuando la norma o la determinación judicial requiere comunicar personalmente.',por:'Asegura conocimiento formal de actos relevantes.',cuida:'Revisar diligencia, domicilio, persona receptora, razón actuarial y fecha en que surte efectos.'},
{t:'Notificación por lista o boletín',d:'Comunicación procesal mediante el medio oficial de publicación previsto por la legislación o por el órgano.',cuando:'Cuando el ordenamiento permite esa forma para una resolución determinada.',por:'Da publicidad procesal y puede activar plazos legales.',cuida:'Comprobar el medio correcto, fecha de publicación y reglas de efectos; no todos los actos se notifican por lista.'},
{t:'Término procesal',d:'Periodo legal o judicial dentro del cual debe realizarse un acto.',cuando:'Al preparar una contestación, recurso, promoción, cumplimiento o cualquier actuación sujeta a plazo.',por:'Ordena la actividad procesal y delimita oportunidades.',cuida:'Distinguir días hábiles y naturales, inicio, vencimiento, suspensiones y reglas particulares del ordenamiento.'},
{t:'Plazo',d:'Lapso fijado para realizar un acto o cumplir una obligación; su tratamiento técnico puede variar según la norma.',cuando:'Al calcular cuándo debe actuarse o cuándo se produce una consecuencia por inactividad.',por:'Permite controlar oportunidad y cumplimiento.',cuida:'No aplicar una regla general sin verificar la ley especial, notificación y calendario oficial.'},
{t:'Cómputo de término',d:'Operación jurídica para determinar inicio, días computables y vencimiento de un término.',cuando:'Cada vez que una actuación depende de un plazo.',por:'Evita extemporaneidad y permite documentar la oportunidad de una actuación.',cuida:'Registrar fuente, fecha de notificación, surtimiento de efectos, días inhábiles, suspensión y regla de vencimiento.'},
{t:'Días hábiles',d:'Días que el ordenamiento y calendario aplicables consideran aptos para actuaciones procesales.',cuando:'Al computar plazos cuando la norma establece días hábiles.',por:'Excluyen los días que legalmente no cuentan para el cómputo.',cuida:'Consultar calendario del órgano y reglas especiales; no todos los procedimientos comparten calendario.'},
{t:'Días naturales',d:'Días consecutivos del calendario, incluidos normalmente sábados, domingos y festivos, salvo regla especial.',cuando:'Cuando la disposición aplicable fija el plazo en días naturales.',por:'Define un cómputo continuo.',cuida:'No sustituir automáticamente días hábiles por naturales ni viceversa.'},
{t:'Suspensión del procedimiento',d:'Interrupción temporal del curso procesal por una causa reconocida legalmente o determinada por autoridad competente.',cuando:'Cuando ocurre un supuesto que impide o suspende la continuación del trámite.',por:'Evita que el proceso avance mientras subsiste la causa legal.',cuida:'Verificar resolución, alcance, fecha de inicio y reanudación; distinguir suspensión de interrupción de un plazo.'},
{t:'Interrupción del plazo',d:'Efecto legal por el cual un plazo deja de correr y puede comenzar un nuevo cómputo conforme a la norma.',cuando:'Cuando una disposición atribuye efecto interruptivo a un acto o circunstancia.',por:'Modifica el cálculo temporal de derechos o actuaciones.',cuida:'No confundir con suspensión; identificar la regla exacta y sus efectos.'},
{t:'Preclusión consumativa',d:'Cierre de una oportunidad procesal por haber ejercido ya la facultad correspondiente, cuando el sistema no permite reiterarla.',cuando:'Al evaluar si una parte puede volver a realizar un acto ya ejercido.',por:'Evita duplicación o reapertura indebida de etapas.',cuida:'Aplicar solo después de comprobar la regla procesal, identidad del acto y posibles excepciones.'},
{t:'Litis',d:'Controversia o materia litigiosa delimitada por las pretensiones, defensas y cuestiones sometidas a decisión.',cuando:'Al identificar qué hechos y cuestiones están realmente controvertidos.',por:'Ayuda a fijar el alcance del debate y la congruencia de la resolución.',cuida:'No incluir como litigioso todo antecedente; revisar demanda, contestación y determinaciones de depuración.'},
{t:'Litisconsorcio',d:'Participación de varias personas como partes actoras o demandadas en una misma relación procesal, en los supuestos reconocidos por la ley.',cuando:'Cuando la relación jurídica o las pretensiones requieren o permiten pluralidad de partes.',por:'Puede evitar decisiones incompatibles y ordenar controversias conexas.',cuida:'Distinguir litisconsorcio activo/pasivo y necesario/facultativo; revisar integración correcta y efectos de omitir a alguien.'},
{t:'Tercero interesado',d:'Persona que, sin ser originalmente una de las partes principales, tiene un interés jurídico que puede verse afectado por el resultado o cuya intervención reconoce la ley.',cuando:'Cuando el procedimiento contempla su llamamiento o comparecencia por interés jurídico.',por:'Protege la posibilidad de defensa y evita decisiones que desconozcan derechos de terceros.',cuida:'La calidad y facultades varían por materia; distinguir interés jurídico de interés meramente económico o simple.'},
{t:'Personalidad',d:'Aptitud procesal para comparecer por propio derecho o en representación de otra persona, conforme a la ley.',cuando:'Al iniciar una actuación o cuando se controvierte la representación.',por:'Permite verificar que quien firma o comparece puede actuar válidamente.',cuida:'Acompañar poder, nombramiento, documentos corporativos o tutela cuando proceda; revisar alcance y vigencia.'},
{t:'Personería',d:'Expresión forense usada para referirse a la representación o acreditación de facultades de quien comparece por otra persona.',cuando:'Al acreditar representación o al responder una objeción sobre ella.',por:'Permite comprobar la capacidad representativa en el expediente.',cuida:'Precisar qué documento confiere facultades y distinguir representación de legitimación en la causa.'},
{t:'Legitimación activa',d:'Vinculación jurídica de quien promueve con la pretensión que hace valer.',cuando:'Al decidir quién está facultado para reclamar una prestación o derecho.',por:'Evita que una persona reclame en nombre propio un derecho ajeno sin habilitación legal.',cuida:'Acreditar titularidad, calidad o habilitación; la exigencia concreta depende de la acción y la materia.'},
{t:'Legitimación pasiva',d:'Vinculación jurídica de la persona contra quien se dirige la pretensión.',cuando:'Al identificar quién debe ser llamado al juicio por la relación jurídica debatida.',por:'Permite dirigir la reclamación contra la persona que jurídicamente corresponde.',cuida:'No confundirla con domicilio o localización; analizar titularidad de la obligación y hechos alegados.'},
{t:'Carga procesal',d:'Conducta que una parte debe realizar en su propio interés para evitar una consecuencia desfavorable, conforme a la ley.',cuando:'Al revisar qué actuaciones conviene o se exige realizar a una parte.',por:'Ordena la actividad de las partes y asigna riesgos de inactividad.',cuida:'Distinguir carga de obligación coercible y de deber de la autoridad; verificar la consecuencia prevista.'},
{t:'Prueba documental pública',d:'Documento al que la ley atribuye carácter público por su origen o forma, con el valor probatorio previsto en el régimen aplicable.',cuando:'Al acreditar actos o hechos formalizados por autoridad o fedatario competente.',por:'Puede demostrar datos asentados oficialmente dentro de sus alcances legales.',cuida:'Revisar autenticidad, competencia, integridad y si el documento acredita el hecho específico discutido.'},
{t:'Prueba documental privada',d:'Documento elaborado por particulares o que no reúne la condición legal de documento público.',cuando:'Al acreditar comunicaciones, acuerdos, pagos, hechos o relaciones entre particulares.',por:'Aporta información que debe incorporarse y valorarse conforme a las reglas aplicables.',cuida:'Verificar autoría, integridad, objeciones, reconocimiento y medios de corroboración.'},
{t:'Prueba pericial',d:'Medio probatorio que requiere conocimientos especializados para analizar hechos o cuestiones técnicas.',cuando:'Cuando el asunto exige conocimiento experto que no se obtiene de la simple percepción judicial.',por:'Ayuda a explicar materias técnicas, científicas, contables, médicas u otras.',cuida:'Definir puntos periciales, especialidad, metodología, documentación base y posibilidad de contradicción.'},
{t:'Prueba testimonial',d:'Declaración de una persona sobre hechos que conoce y que son relevantes para el litigio.',cuando:'Cuando un testigo puede declarar sobre hechos controvertidos y la ley permite su recepción.',por:'Puede contribuir a probar hechos mediante conocimiento personal.',cuida:'Distinguir percepción directa de referencias; preparar preguntas lícitas y revisar citación, tachas y contradicción.'},
{t:'Inspección judicial',d:'Actuación en la que la autoridad observa directamente lugares, objetos o situaciones relevantes, según las reglas procesales.',cuando:'Cuando la percepción directa del objeto puede aportar información al litigio.',por:'Permite documentar características que requieren constatación.',cuida:'Delimitar objeto, puntos de inspección, participación de partes y registro de resultados.'},
{t:'Objeción de prueba',d:'Cuestionamiento formulado contra la admisión, autenticidad, alcance o valoración de un medio probatorio, según la oportunidad procesal.',cuando:'Cuando existe una razón jurídica o fáctica concreta para controvertir una prueba.',por:'Permite señalar defectos y proteger el derecho de contradicción.',cuida:'Identificar qué se objeta, por qué, con qué fundamento y en qué momento; no todas las objeciones tienen la misma vía.'},
{t:'Valoración probatoria',d:'Actividad de analizar los medios de prueba para determinar qué hechos se consideran acreditados.',cuando:'Al formular alegatos, estudiar una resolución o preparar agravios.',por:'Conecta las pruebas con las conclusiones fácticas del asunto.',cuida:'Examinar prueba individual y conjunta, reglas de valoración, inferencias y motivación.'},
{t:'Alegato de apertura',d:'Exposición inicial, cuando la vía lo contempla, sobre la teoría del caso y lo que se espera demostrar.',cuando:'Al inicio de la audiencia de juicio en los procedimientos que prevén esta intervención.',por:'Orienta al tribunal sobre la controversia y la prueba que se presentará.',cuida:'No presentarlo como prueba ni prometer hechos que no puedan sostenerse.'},
{t:'Alegato de clausura',d:'Argumentación final que relaciona la prueba desahogada con los hechos y la consecuencia jurídica solicitada.',cuando:'Al cerrar la etapa probatoria, cuando la ley permite alegar.',por:'Explica por qué el material probatorio apoya la teoría del caso.',cuida:'Referirse a pruebas efectivamente incorporadas, abordar puntos débiles y formular una petición concreta.'},
{t:'Convenio judicialmente aprobado',d:'Acuerdo de las partes al que la autoridad otorga aprobación o efectos procesales conforme a la ley.',cuando:'Cuando existe arreglo válido y la materia permite disponer de los derechos involucrados.',por:'Puede poner fin al litigio o regular obligaciones exigibles.',cuida:'Verificar capacidad, consentimiento, derechos indisponibles, claridad de obligaciones y efectos de incumplimiento.'},
{t:'Transacción',d:'Contrato o acuerdo por el que las partes, mediante concesiones recíprocas, previenen o terminan una controversia, conforme a la legislación aplicable.',cuando:'Al negociar una solución de una disputa o evitar un litigio.',por:'Reduce incertidumbre y puede definir obligaciones o renuncias válidas.',cuida:'Revisar capacidad, alcance, concesiones, derechos no disponibles, forma y efectos de cosa juzgada cuando proceda.'},
{t:'Mediación',d:'Mecanismo en el que una persona facilitadora ayuda a las partes a construir voluntariamente una solución.',cuando:'Cuando el conflicto puede resolverse mediante un mecanismo alternativo y las partes participan conforme a la ley.',por:'Facilita acuerdos sin que la persona mediadora imponga la solución.',cuida:'Verificar voluntariedad, confidencialidad, materia disponible y requisitos para formalizar el acuerdo.'},
{t:'Conciliación',d:'Mecanismo de solución en el que la persona conciliadora puede facilitar el diálogo y, según el régimen, proponer alternativas.',cuando:'Cuando la ley exige o permite una etapa conciliatoria o las partes la eligen.',por:'Busca resolver total o parcialmente la controversia.',cuida:'Distinguir conciliación judicial, prejudicial y privada; comprobar obligatoriedad, excepciones y efectos del convenio.'},
{t:'Laudo',d:'Resolución emitida por un tribunal arbitral o por una autoridad a la que la legislación atribuye esa denominación, según la materia.',cuando:'Al concluir el procedimiento arbitral o en los supuestos laborales históricos o especiales que correspondan.',por:'Resuelve la controversia sometida a esa jurisdicción o procedimiento.',cuida:'No usarlo como sinónimo universal de sentencia; identificar el régimen, autoridad y medios de impugnación o ejecución.'},
{t:'Arbitraje',d:'Mecanismo por el que las partes someten una controversia a una persona o tribunal arbitral en los casos permitidos.',cuando:'Cuando existe convenio arbitral válido y la materia admite arbitraje.',por:'Permite una decisión fuera de la jurisdicción estatal ordinaria, con los efectos legales correspondientes.',cuida:'Verificar arbitrabilidad, convenio, alcance, procedimiento, medidas de apoyo y requisitos de reconocimiento o ejecución.'},
{t:'Jurisdicción voluntaria',d:'Procedimiento de intervención judicial sin una controversia entre partes en sentido contencioso, en los supuestos previstos por la ley.',cuando:'Para solicitudes como determinadas autorizaciones, informaciones o actuaciones no contenciosas.',por:'Permite obtener intervención o constancia judicial cuando el ordenamiento lo exige.',cuida:'Confirmar que no exista controversia que obligue a una vía contenciosa y revisar requisitos específicos.'},
{t:'Diligencias preliminares',d:'Actuaciones previas al juicio autorizadas por la ley para preparar la demanda, precisar elementos o conservar información.',cuando:'Antes de demandar, si se actualiza un supuesto expresamente previsto.',por:'Ayudan a preparar correctamente la acción o reunir elementos necesarios.',cuida:'No confundir con investigación libre: debe existir fundamento y cumplir límites legales.'},
{t:'Providencia precautoria',d:'Medida provisional prevista por la ley para proteger bienes, personas o eficacia de una futura resolución en determinados supuestos.',cuando:'Cuando se cumplen los requisitos legales de urgencia, riesgo y garantía, si se exige.',por:'Busca evitar que el resultado del juicio se vuelva ineficaz.',cuida:'Distinguir de otras medidas cautelares; identificar norma, riesgo concreto, proporcionalidad y contragarantía cuando proceda.'},
{t:'Embargo',d:'Afectación jurídica de bienes para asegurar una obligación o hacer efectiva una ejecución conforme a la ley.',cuando:'Como medida de aseguramiento o en ejecución, cuando se cumplen los presupuestos legales.',por:'Preserva bienes o permite su realización para satisfacer una obligación.',cuida:'Revisar orden, bienes embargables, proporcionalidad, derechos de terceros y formalidades de ejecución.'},
{t:'Remate judicial',d:'Procedimiento de venta de bienes sujeto a ejecución judicial para aplicar el producto al pago conforme a la ley.',cuando:'Cuando existe ejecución y se reúnen los requisitos para la realización de bienes.',por:'Convierte bienes en recursos para cumplir una resolución.',cuida:'Verificar avalúo, convocatoria, postura legal, derechos preferentes y notificaciones.'},
{t:'Adjudicación',d:'Atribución jurídica de un bien o derecho a una persona por resolución, procedimiento o acto reconocido legalmente.',cuando:'En remates, sucesiones, licitaciones u otros procedimientos que la contemplen.',por:'Determina quién adquiere el bien o derecho y en qué condiciones.',cuida:'Comprobar título, firmeza, pagos, inscripción y cargas que subsistan.'},
{t:'Exhorto',d:'Comunicación formal por la que un órgano jurisdiccional solicita a otro que practique una actuación dentro de sus atribuciones.',cuando:'Cuando una diligencia debe realizarse fuera del ámbito territorial del órgano que conoce.',por:'Permite cooperación entre autoridades judiciales.',cuida:'Verificar autoridad exhortada, objeto, anexos, diligenciamiento y devolución de constancias.'},
{t:'Despacho judicial',d:'Comunicación o instrumento de cooperación entre autoridades para practicar actuaciones, conforme a la terminología del régimen aplicable.',cuando:'Cuando la legislación prevé esta vía de comunicación para una diligencia.',por:'Facilita que una autoridad practique actos solicitados por otra.',cuida:'La diferencia entre despacho, exhorto y requisitoria depende del ordenamiento; usar la denominación legal concreta.'},
{t:'Oficio',d:'Comunicación formal emitida por una autoridad o institución para solicitar, informar o transmitir una determinación.',cuando:'Para comunicaciones oficiales con autoridades, entidades o personas en los supuestos procedentes.',por:'Deja constancia de una petición o comunicación institucional.',cuida:'Identificar destinatario, expediente, objeto, firma, anexos y constancia de recepción.'},
{t:'Copias certificadas',d:'Reproducciones cuya correspondencia con el documento o expediente original es certificada por autoridad facultada.',cuando:'Cuando se requiere acreditar actuaciones o documentos en otro trámite o para consulta formal.',por:'Aportan una reproducción con certificación oficial en los alcances legales.',cuida:'Verificar autoridad certificante, integridad, páginas, sellos o firma electrónica y requisitos de expedición.'},
{t:'Acceso a expediente',d:'Facultad de consultar actuaciones de un procedimiento por quienes tengan derecho a ello, con límites de reserva y protección de datos.',cuando:'Cuando una parte o representante necesita revisar constancias para ejercer defensa o preparar una actuación.',por:'Permite conocer el estado real del procedimiento y sus documentos.',cuida:'Acreditar personalidad, respetar datos reservados y verificar si la consulta es física o electrónica.'},
{t:'Expediente electrónico',d:'Conjunto de actuaciones y documentos procesales gestionados en un sistema digital autorizado.',cuando:'Cuando el órgano jurisdiccional opera con expediente digital o permite actuaciones electrónicas.',por:'Facilita consulta, presentación y seguimiento de actuaciones.',cuida:'Revisar reglas de firma, acuse, sello de tiempo, notificación electrónica, integridad y acceso.'},
{t:'Firma electrónica',d:'Datos o mecanismo electrónico utilizados para identificar a una persona y expresar su aprobación o autoría, con efectos definidos por la normativa aplicable.',cuando:'Al presentar promociones o realizar actos electrónicos cuando el sistema la admite o exige.',por:'Permite autenticar actos y documentos en entornos digitales.',cuida:'Distinguir tipos de firma, certificados, vigencia, uso autorizado y reglas del sistema judicial.'},
{t:'Acuse de recibo',d:'Constancia de que una presentación o comunicación fue recibida por el destinatario o sistema.',cuando:'Después de presentar un escrito o transmitir un documento.',por:'Permite acreditar recepción y fecha, sin que necesariamente pruebe admisión o procedencia.',cuida:'Conservar folio, sello de tiempo, archivo enviado y anexos; no confundir recibido con acordado.'},
{t:'Turno judicial',d:'Asignación de un asunto a un órgano, juzgado o ponencia conforme a reglas de distribución.',cuando:'Después de la recepción o registro del asunto.',por:'Distribuye el conocimiento del expediente entre autoridades competentes.',cuida:'El turno no equivale por sí mismo a admisión de demanda ni a una decisión de fondo.'},
{t:'Radicación',d:'Registro y asunción inicial del conocimiento de un asunto por el órgano correspondiente, según la práctica y la ley.',cuando:'Cuando el expediente se registra o el órgano dicta la determinación inicial pertinente.',por:'Identifica formalmente el asunto en el órgano.',cuida:'Distinguir radicación de admisión, emplazamiento y resolución sobre procedencia.'},
{t:'Acumulación de autos',d:'Unión procesal de expedientes relacionados cuando la ley lo permite, para tramitarlos o resolverlos coordinadamente.',cuando:'Cuando existen procedimientos vinculados y se satisfacen los requisitos legales de acumulación.',por:'Puede evitar sentencias contradictorias y duplicación de actuaciones.',cuida:'Revisar competencia, conexidad, etapa de cada asunto y efectos sobre plazos.'},
{t:'Separación de autos',d:'Decisión de tramitar por separado asuntos o cuestiones que se habían unido, cuando el ordenamiento lo permite.',cuando:'Cuando la acumulación deja de ser adecuada o la ley autoriza separar procedimientos.',por:'Facilita una tramitación ordenada de asuntos que requieren curso independiente.',cuida:'Identificar qué expediente continúa, cómo se conservan constancias y qué ocurre con términos y pruebas.'},
{t:'Excusa judicial',d:'Manifestación de la persona juzgadora para dejar de conocer un asunto por una causa legal de impedimento.',cuando:'Cuando concurre una circunstancia prevista por la ley que afecta o puede afectar la imparcialidad.',por:'Protege imparcialidad y confianza en la decisión.',cuida:'La causa debe encuadrar en la norma; no es equivalente a recusación promovida por una parte.'},
{t:'Recusación',d:'Solicitud de una parte para que una persona juzgadora se aparte del asunto por una causa legal de impedimento.',cuando:'Cuando existen hechos que encuadran en una causal prevista por el ordenamiento.',por:'Busca garantizar imparcialidad del órgano jurisdiccional.',cuida:'Revisar causal, oportunidad, prueba, trámite y efectos; una mera inconformidad con decisiones no basta por sí sola.'},
{t:'Impedimento judicial',d:'Circunstancia legal que puede impedir a una persona juzgadora conocer de un asunto por razones de imparcialidad u otras previstas.',cuando:'Cuando se identifica una causal legal en el caso concreto.',por:'Protege independencia e imparcialidad en la decisión.',cuida:'Distinguir impedimento, excusa y recusación según quién lo plantea y el procedimiento aplicable.'},
{t:'Amparo directo',d:'Medio de control constitucional que, en términos generales, procede contra determinadas sentencias definitivas, laudos o resoluciones que ponen fin al juicio.',cuando:'Cuando se cumplen los supuestos constitucionales y legales de procedencia frente a la resolución correspondiente.',por:'Permite examinar violaciones constitucionales en los casos previstos.',cuida:'Verificar definitividad, excepciones, autoridad responsable, tercero interesado, plazo y requisitos de la Ley de Amparo.'},
{t:'Amparo indirecto',d:'Medio de control constitucional que procede contra actos y normas en los supuestos previstos por la Constitución y la Ley de Amparo.',cuando:'Cuando el acto reclamado encuadra en alguno de los supuestos legales de procedencia.',por:'Permite solicitar protección constitucional en los casos que no corresponden al amparo directo.',cuida:'Determinar acto, autoridad, interés, plazo, definitividad, suspensión y causales de improcedencia.'},
{t:'Suspensión del acto reclamado',d:'Medida cautelar dentro del juicio de amparo que puede paralizar o modular temporalmente los efectos del acto reclamado conforme a la ley.',cuando:'Cuando se solicita o procede de oficio en los supuestos previstos y se satisfacen los requisitos legales.',por:'Busca preservar la materia del juicio y evitar afectaciones durante su tramitación.',cuida:'No equivale a sentencia favorable; revisar interés social, orden público, apariencia del buen derecho y efectos concretos.'},
{t:'Interés jurídico',d:'Afectación directa a un derecho subjetivo protegido, en los términos exigidos por el régimen aplicable.',cuando:'Al justificar la legitimación para promover un medio de defensa o procedimiento.',por:'Permite mostrar que el acto afecta una posición jurídica propia.',cuida:'No confundir con interés simple o legítimo; el estándar depende del tipo de juicio y norma.'},
{t:'Interés legítimo',d:'Posición especial frente al orden jurídico que puede habilitar la impugnación cuando se satisfacen los requisitos constitucionales y legales.',cuando:'En los procedimientos que permiten promover con base en interés legítimo.',por:'Amplía el acceso a la justicia más allá de la titularidad de un derecho subjetivo, bajo condiciones específicas.',cuida:'Acreditar afectación real y diferenciada y revisar el estándar del medio de defensa concreto.'},
{t:'Definitividad',d:'Principio o requisito que, en ciertos medios de defensa, exige agotar recursos ordinarios disponibles antes de acudir a una vía extraordinaria.',cuando:'Al determinar si puede promoverse amparo u otro medio de control.',por:'Coordina los medios de impugnación y el carácter subsidiario de determinadas vías.',cuida:'Revisar excepciones legales y jurisprudenciales; no asumir que siempre debe agotarse todo recurso.'},
{t:'Agravio inoperante',d:'Argumento de impugnación que no puede conducir a modificar la resolución por deficiencias relevantes, falta de combate a razones esenciales u otra causa jurídica.',cuando:'Al analizar agravios o estudiar una resolución de alzada.',por:'Identifica argumentos que no controvierten eficazmente el fundamento de la decisión.',cuida:'La calificación depende del caso y del criterio aplicable; explicar la razón concreta sin usar etiquetas vacías.'},
{t:'Agravio fundado',d:'Argumento de impugnación que demuestra un error o violación jurídicamente relevante en la resolución combatida.',cuando:'Al estudiar un recurso o sentencia de revisión.',por:'Puede justificar modificación, revocación o reposición según su alcance.',cuida:'Separar que el agravio sea fundado de que sea suficiente para obtener todo lo pedido.'},
{t:'Revocación',d:'Medio de impugnación o facultad legal para pedir o disponer que una resolución sea dejada sin efectos o modificada, según la materia.',cuando:'Cuando la ley prevé revocación para la resolución y autoridad específicas.',por:'Permite revisar decisiones en los términos del ordenamiento.',cuida:'No confundir recurso de revocación con facultad administrativa de revocar; verificar autoridad, plazo y procedencia.'},
{t:'Apelación',d:'Medio de impugnación mediante el cual se solicita a un órgano superior revisar una resolución en los términos legales.',cuando:'Cuando la resolución es apelable y se cumplen los requisitos y plazo.',por:'Puede buscar confirmación, modificación o revocación de la decisión.',cuida:'Identificar efecto, trámite, agravios, copias, autoridad y plazo de la legislación aplicable.'},
{t:'Queja',d:'Denominación de diversos medios de impugnación o mecanismos de inconformidad previstos por distintas leyes.',cuando:'Solo cuando la legislación específica contempla una queja para el acto o problema.',por:'Permite obtener revisión o control en supuestos concretos.',cuida:'No existe una queja universal: identificar ley, autoridad competente, plazo y objeto exacto.'},
{t:'Revocación de mandato',d:'Figura jurídica o político-constitucional distinta del recurso procesal de revocación.',cuando:'En los procedimientos constitucionales o legales que la regulan.',por:'Permite someter la continuidad de una persona en un cargo a un mecanismo previsto normativamente.',cuida:'No confundir con revocar una resolución judicial o administrativa.'},
{t:'Ampliación de demanda',d:'Modificación o complemento de una demanda inicial en los supuestos y plazos que permite la ley.',cuando:'Cuando surgen hechos, actos, autoridades o elementos que legalmente pueden incorporarse.',por:'Permite ajustar el planteamiento inicial dentro de límites procesales.',cuida:'No siempre se permite; revisar oportunidad, causa, congruencia, traslado a la contraparte y requisitos.'},
{t:'Modificación de demanda',d:'Cambio de la demanda en aspectos permitidos por la legislación, antes o durante la etapa autorizada.',cuando:'Cuando la ley permite ajustar pretensiones, hechos o partes en la fase concreta.',por:'Puede corregir o precisar el objeto litigioso.',cuida:'Distinguir modificación, aclaración y ampliación; valorar consentimiento, preclusión y afectación a la defensa.'},
{t:'Aclaración de sentencia',d:'Solicitud o actuación destinada a precisar una expresión ambigua, contradicción u omisión formal dentro de los límites legales, sin reabrir libremente el fondo.',cuando:'Cuando la resolución contiene una oscuridad, omisión o contradicción que la norma permite aclarar.',por:'Busca hacer comprensible o coherente la resolución.',cuida:'Verificar plazo, autoridad y límites; puede afectar el cómputo de impugnación solo cuando la ley lo disponga.'},
{t:'Liquidación de sentencia',d:'Determinación de cantidades o conceptos que requieren cálculo para concretar una condena, conforme a la resolución y la ley.',cuando:'Cuando la sentencia reconoce una obligación que necesita cuantificarse.',por:'Convierte una condena genérica o pendiente de cálculo en una suma determinada.',cuida:'Seguir bases fijadas en sentencia, exhibir cálculos y comprobantes, y respetar contradicción y términos.'},
{t:'Incidente de liquidación',d:'Trámite accesorio para resolver controversias sobre la cuantificación de una condena o prestación.',cuando:'Cuando existe una condena por cuantificar y el ordenamiento prevé incidente.',por:'Permite determinar el monto exigible.',cuida:'No modificar lo decidido en sentencia; separar cuantificación de cuestiones ya juzgadas.'},
{t:'Cumplimiento de sentencia',d:'Ejecución voluntaria o forzosa de lo ordenado en una resolución, conforme a sus términos y a la ley.',cuando:'Después de que la obligación sea exigible y no se haya cumplido espontáneamente.',por:'Materializa la tutela reconocida por la autoridad.',cuida:'Verificar alcance, plazo, modalidad, cumplimiento parcial y vía de ejecución.'},
{t:'Incidente de incumplimiento',d:'Procedimiento accesorio o mecanismo legal para resolver una alegación de incumplimiento de una determinación, cuando esté previsto.',cuando:'Cuando una parte sostiene que no se ejecutó una orden o convenio y existe trámite para plantearlo.',por:'Busca que se determine el incumplimiento y sus consecuencias.',cuida:'Identificar el mecanismo específico de la materia; no todos los incumplimientos se tramitan incidentalmente.'},
{t:'Costas procesales',d:'Gastos del proceso cuya recuperación o imposición se rige por la ley y por la decisión judicial.',cuando:'Al reclamar gastos o al resolver quién debe cubrirlos en los supuestos legales.',por:'Distribuye ciertos costos del litigio conforme al régimen aplicable.',cuida:'Distinguir costas de gastos particulares y honorarios; no asumir que siempre se condena a la parte vencida.'},
{t:'Gastos y costas',d:'Expresión usada para referirse a erogaciones procesales y costas en los términos de la ley.',cuando:'Al formular una prestación o solicitar condena relacionada con costos del litigio.',por:'Busca obtener la recuperación de conceptos legalmente reconocidos.',cuida:'Precisar conceptos, prueba y fundamento; su procedencia depende de materia y resultado.'},
{t:'Condena',d:'Determinación judicial que impone una obligación o consecuencia jurídica a una parte.',cuando:'Al dictarse resolución de fondo o una decisión que legalmente imponga un deber.',por:'Establece lo que debe darse, hacerse, pagarse o soportarse.',cuida:'Distinguir condena principal, accesoria, líquida e ilíquida; revisar plazo y ejecución.'},
{t:'Absolución',d:'Decisión que libera a una parte de una pretensión o imputación en los alcances de la resolución.',cuando:'Cuando el órgano determina que no procede imponer la consecuencia reclamada o imputada.',por:'Define que no se impone la condena pretendida, según el ámbito de la decisión.',cuida:'No inferir todos sus efectos sin leer los puntos resolutivos y la causa de absolución.'},
{t:'Sentencia declarativa',d:'Resolución que reconoce la existencia, inexistencia o alcance de una relación o situación jurídica.',cuando:'Cuando la pretensión busca certeza o reconocimiento jurídico.',por:'Elimina incertidumbre sobre una situación legal.',cuida:'Identificar efectos concretos, legitimación, cosa juzgada y si requiere actos posteriores.'},
{t:'Sentencia constitutiva',d:'Resolución que crea, modifica o extingue una situación jurídica cuando el ordenamiento atribuye ese efecto a la decisión.',cuando:'Cuando la pretensión y la norma permiten que el fallo produzca ese cambio jurídico.',por:'Transforma una relación o estado jurídico en los términos de la ley.',cuida:'Comprobar cuándo surte efectos y si requiere inscripción o comunicación a otra autoridad.'},
{t:'Sentencia de condena',d:'Resolución que ordena a una parte cumplir una prestación o conducta.',cuando:'Cuando se acredita una obligación exigible y procede imponer su cumplimiento.',por:'Permite exigir una conducta y, cuando corresponda, iniciar ejecución.',cuida:'Verificar si la condena es líquida, plazo, intereses, accesorios y reglas de ejecución.'},
{t:'Firmeza parcial',d:'Situación en que una parte de la resolución puede quedar firme aunque otros puntos continúen impugnados, si el ordenamiento lo permite.',cuando:'Cuando la impugnación no comprende todos los puntos o la ley reconoce firmeza separable.',por:'Permite delimitar qué cuestiones ya no están abiertas a revisión.',cuida:'Analizar resolutivos, alcance del recurso y reglas de divisibilidad; no presumirla.'},
{t:'Ejecutabilidad provisional',d:'Posibilidad legal de ejecutar una resolución antes de que adquiera firmeza, si el ordenamiento lo autoriza.',cuando:'Cuando existe una norma o determinación que permite ejecución provisional.',por:'Puede adelantar efectos de la decisión bajo condiciones legales.',cuida:'No confundir con sentencia firme; revisar garantías, suspensión y riesgos de revocación.'},
{t:'Efecto devolutivo',d:'Efecto de un recurso que permite al órgano superior conocer de la impugnación sin que necesariamente se suspenda la ejecución, conforme a la ley.',cuando:'Al analizar el efecto en que se admite un recurso.',por:'Define qué autoridad revisa y cómo continúa el procedimiento.',cuida:'Su alcance varía por recurso y código; leer la disposición específica.'},
{t:'Efecto suspensivo',d:'Efecto procesal por el que la impugnación suspende, en los términos legales, la ejecución o continuación de determinados actos.',cuando:'Cuando la ley atribuye ese efecto al recurso o la autoridad lo concede válidamente.',por:'Evita que ciertos efectos se consumen mientras se revisa la resolución.',cuida:'No presumir suspensión por el solo hecho de recurrir; verificar norma y resolución.'},
{t:'Incidente de nulidad de notificaciones',d:'Trámite para cuestionar la validez de una notificación por defectos que satisfagan los requisitos legales.',cuando:'Cuando se sostiene que la notificación no cumplió las formalidades y afectó derechos procesales.',por:'Busca corregir efectos procesales derivados de una comunicación irregular.',cuida:'Revisar oportunidad, conocimiento efectivo, convalidación, perjuicio y reglas del código.'},
{t:'Acumulación de pretensiones',d:'Planteamiento conjunto de varias pretensiones en una demanda cuando se cumplen los requisitos legales.',cuando:'Al formular la demanda si las pretensiones son compatibles y la vía permite tramitarlas juntas.',por:'Puede resolver en un solo proceso cuestiones relacionadas.',cuida:'Revisar competencia, vía, compatibilidad, cuantía, sujetos y requisitos especiales.'},
{t:'Conexidad',d:'Relación relevante entre asuntos, hechos o pretensiones que puede justificar tratamiento conjunto o consecuencias procesales.',cuando:'Al valorar acumulación, competencia o coordinación de procedimientos.',por:'Ayuda a evitar decisiones incompatibles y analizar relaciones entre casos.',cuida:'La conexión debe encuadrar en la norma; semejanza temática por sí sola puede no bastar.'},
{t:'Competencia por materia',d:'Asignación del asunto según el tipo de relación jurídica o área del Derecho involucrada.',cuando:'Antes de presentar una demanda o al cuestionar el órgano que conoce.',por:'Determina qué órgano especializado debe conocer.',cuida:'Revisar pretensión real y reglas legales, no solo el nombre que la parte da a su demanda.'},
{t:'Competencia territorial',d:'Asignación de asuntos según el lugar previsto por la ley, como domicilio, cumplimiento u otro punto de conexión.',cuando:'Al decidir ante qué órgano territorial presentar o tramitar el asunto.',por:'Identifica la sede territorial competente.',cuida:'Las reglas pueden ser imperativas o admitir prórroga según la materia; verificar pactos y excepciones.'},
{t:'Competencia por cuantía',d:'Asignación de asuntos según el valor económico de la controversia cuando la ley utiliza ese criterio.',cuando:'Al determinar el órgano competente en procedimientos que atienden a cuantía.',por:'Distribuye asuntos según umbrales establecidos legalmente.',cuida:'Calcular con la regla correcta y fecha relevante; revisar prestaciones accesorias y actualización de umbrales.'},
{t:'Vía procesal',d:'Tipo de procedimiento legal mediante el cual debe tramitarse una pretensión.',cuando:'Antes de presentar la demanda y al revisar excepciones de vía.',por:'Determina etapas, requisitos, plazos y medios de defensa.',cuida:'No todas las vías son intercambiables; justificar la vía conforme a acción, materia y ley vigente.'},
{t:'Acción ejercitada',d:'Pretensión o tutela específica que el actor intenta obtener mediante el proceso, conforme a la clasificación doctrinal y legal aplicable.',cuando:'Al diseñar demanda y precisar qué decisión se pide.',por:'Permite ordenar hechos, prestaciones y fundamento.',cuida:'No confundir nombre doctrinal de la acción con la procedencia legal concreta.'},
{t:'Prestaciones reclamadas',d:'Beneficios, declaraciones, pagos u obligaciones concretas que el actor solicita al tribunal.',cuando:'Al formular la demanda y delimitar lo que se pide.',por:'Fijan el alcance de la tutela solicitada y de la defensa.',cuida:'Deben ser claras, compatibles y congruentes con hechos y fundamento; revisar accesorios y cuantificación.'},
{t:'Hechos constitutivos',d:'Hechos que, de acreditarse, integran los elementos de la pretensión conforme a la norma sustantiva.',cuando:'Al construir la teoría del caso y organizar demanda o contestación.',por:'Conectan la situación fáctica con los requisitos legales del derecho reclamado.',cuida:'Identificar cada elemento de la norma y asociarlo con hechos y pruebas.'},
{t:'Hechos impeditivos',d:'Hechos que impiden que nazca o produzca efectos la consecuencia jurídica pretendida, conforme a la norma.',cuando:'Al preparar defensas o analizar los elementos de la pretensión.',por:'Pueden impedir la procedencia de la reclamación aunque existan otros hechos alegados.',cuida:'Precisar carga probatoria y regla aplicable; no etiquetar sin análisis.'},
{t:'Hechos extintivos',d:'Hechos que, conforme a la ley, extinguen una obligación o derecho previamente existente.',cuando:'Al formular defensas basadas en pago, cumplimiento, remisión u otra causa legal.',por:'Explican por qué la obligación ya no sería exigible.',cuida:'Acreditar fecha, alcance y requisitos de la causa extintiva.'},
{t:'Teoría del caso',d:'Explicación organizada de los hechos, la prueba y el derecho que una parte sostiene para obtener una decisión favorable.',cuando:'Al preparar un litigio y planear escritos, prueba, audiencia y alegatos.',por:'Da coherencia a la estrategia y conecta cada afirmación con evidencia y norma.',cuida:'Debe ser verificable, consistente y adaptable a la prueba; no reemplaza los requisitos procesales.'},
{t:'Prueba superveniente',d:'Medio de prueba que surge o se conoce después de la oportunidad ordinaria, admitido solo bajo condiciones legales.',cuando:'Cuando la prueba no pudo ofrecerse antes por una causa reconocida por el ordenamiento.',por:'Permite incorporar evidencia posterior sin desconocer la preclusión.',cuida:'Justificar cuándo y cómo se conoció, por qué no se ofreció antes y cumplir traslado y requisitos.'},
{t:'Hecho notorio',d:'Hecho que, conforme al estándar legal aplicable, puede ser conocido o tenido por cierto sin prueba ordinaria en determinadas condiciones.',cuando:'Al argumentar que una circunstancia no requiere demostración probatoria ordinaria.',por:'Evita probar hechos ampliamente conocidos o reconocibles en el contexto legal pertinente.',cuida:'No confundir notoriedad con conocimiento personal del juzgador; justificar por qué satisface el estándar.'},
{t:'Presunción legal',d:'Inferencia establecida por la ley a partir de determinados hechos, con el efecto probatorio que el ordenamiento le atribuya.',cuando:'Cuando se acredita el hecho base de la presunción.',por:'Puede facilitar la prueba o desplazar cargas conforme a la norma.',cuida:'Distinguir presunción absoluta y relativa; revisar hechos base y posibilidad de prueba en contrario.'},
{t:'Principio de congruencia',d:'Exigencia de que la resolución guarde correspondencia con las pretensiones, defensas y cuestiones sometidas a decisión.',cuando:'Al redactar una demanda o revisar una sentencia.',por:'Evita resolver cuestiones ajenas u omitir puntos que debían decidirse.',cuida:'Comparar peticiones, debate procesal y resolutivos; revisar regla aplicable.'},
{t:'Principio de exhaustividad',d:'Exigencia de examinar y resolver las cuestiones relevantes planteadas y que deban decidirse.',cuando:'Al evaluar la motivación de una resolución o preparar agravios.',por:'Permite detectar omisiones decisorias.',cuida:'Identificar el planteamiento omitido, su relevancia y la norma que exige respuesta.'},
{t:'Fundamentación',d:'Identificación de las normas o bases jurídicas que sustentan una decisión o petición.',cuando:'En promociones, demandas, resoluciones y argumentos jurídicos.',por:'Muestra la regla jurídica invocada para la consecuencia solicitada.',cuida:'La cita por sí sola no basta: verificar texto, vigencia, aplicabilidad y relación con los hechos.'},
{t:'Motivación',d:'Exposición de razones fácticas y jurídicas que explican por qué se adopta una decisión.',cuando:'Al dictar actos de autoridad y al analizar su legalidad.',por:'Permite comprender y controvertir el razonamiento decisorio.',cuida:'Distinguir razones aparentes de un análisis real de hechos, pruebas y norma.'},
{t:'Excepción procesal',d:'Defensa dirigida a cuestionar un presupuesto o requisito del procedimiento, según el ordenamiento.',cuando:'En la oportunidad establecida para controvertir competencia, personalidad u otros presupuestos.',por:'Busca que se resuelva un obstáculo procesal antes o durante el fondo.',cuida:'Clasificación, oportunidad y trámite dependen del código; no toda defensa es excepción procesal.'},
{t:'Excepción de fondo',d:'Defensa sustantiva que busca demostrar que la pretensión no existe, no es exigible o se extinguió, conforme a la ley.',cuando:'Al contestar o en el momento procesal previsto.',por:'Controvierte los elementos materiales de la pretensión.',cuida:'Relacionar hechos, pruebas y norma; revisar carga probatoria y oportunidad.'},
{t:'Reconvención conexa',d:'Pretensión del demandado frente al actor que se plantea en el mismo proceso y guarda la relación exigida por la ley, cuando proceda.',cuando:'En la oportunidad y vía que permitan formularla.',por:'Permite que pretensiones relacionadas se resuelvan coordinadamente.',cuida:'Verificar conexidad, competencia, prestaciones, anexos y plazo.'},
{t:'Allanamiento',d:'Aceptación de la pretensión o de aspectos de ella por la parte demandada, con los efectos que la ley establezca.',cuando:'Cuando la parte decide aceptar total o parcialmente lo reclamado.',por:'Puede simplificar la controversia y afectar la necesidad de prueba o el sentido de la decisión.',cuida:'Revisar capacidad, alcance, derechos indisponibles y si se requiere ratificación o control judicial.'},
{t:'Confesión',d:'Reconocimiento de hechos propios que puede tener efectos probatorios según la forma y régimen aplicables.',cuando:'En las modalidades y oportunidades reconocidas por la ley.',por:'Puede acreditar hechos controvertidos dentro de sus límites.',cuida:'Distinguir confesión judicial, extrajudicial y declaración de parte; analizar contexto, indivisibilidad y valoración.'},
{t:'Reconocimiento de firma y contenido',d:'Actuación destinada a confirmar autoría o reconocimiento de un documento, en los casos que la ley prevé.',cuando:'Cuando se cuestiona o necesita acreditar la autoría de un documento privado.',por:'Puede incidir en su autenticidad y eficacia probatoria.',cuida:'Seguir el procedimiento de la materia; no asumir que reconocer firma demuestra automáticamente todos los hechos del documento.'},
{t:'Tacha de testigos',d:'Objeción basada en circunstancias legalmente relevantes para valorar credibilidad o idoneidad de un testigo, según el régimen.',cuando:'Cuando se conocen circunstancias que la ley permite hacer valer respecto del testimonio.',por:'Permite al órgano valorar el testimonio con contexto relevante.',cuida:'Verificar si el código contempla formalmente la tacha y su oportunidad; distinguirla de contradicción en interrogatorio.'},
{t:'Cadena de custodia',d:'Registro documentado del manejo y conservación de indicios o evidencias, especialmente relevante en materia penal.',cuando:'Desde la localización o aseguramiento de indicios en los supuestos normativos correspondientes.',por:'Protege integridad, identidad y trazabilidad de la evidencia.',cuida:'Aplicación y consecuencias dependen del régimen; una irregularidad requiere análisis concreto de impacto y autenticidad.'},
{t:'Presunción de inocencia',d:'Garantía por la que una persona debe ser tratada como inocente y la culpabilidad debe acreditarse conforme al estándar penal aplicable.',cuando:'Durante el procedimiento penal y al valorar la carga y suficiencia de la prueba.',por:'Limita el trato y la decisión estatal hasta que se cumplan los requisitos de condena.',cuida:'No reducirla a una frase; analizar carga probatoria, estándar de prueba, trato procesal y resolución.'},
{t:'Principio pro persona',d:'Criterio interpretativo constitucional de derechos humanos que orienta a favorecer la protección más amplia dentro del marco jurídico aplicable.',cuando:'Al interpretar normas de derechos humanos cuando exista una cuestión real de alcance o interpretación.',por:'Orienta la selección o interpretación normativa conforme a sus condiciones jurídicas.',cuida:'No autoriza ignorar competencias, reglas de procedencia ni toda restricción; argumentar la interpretación concreta.'},
{t:'Control de convencionalidad',d:'Examen de compatibilidad de normas y actos con obligaciones internacionales de derechos humanos, en el marco de competencias y criterios aplicables.',cuando:'Cuando una cuestión de derechos humanos requiere analizar tratados y estándares pertinentes.',por:'Contribuye a la protección de derechos en los términos reconocidos por el sistema jurídico.',cuida:'Identificar tratado, norma, criterio interpretativo, autoridad competente y alcance del control.'},
{t:'Jurisprudencia',d:'Criterios jurídicos que tienen la fuerza y obligatoriedad que les asigna el sistema de fuentes aplicable.',cuando:'Al sustentar interpretación jurídica o revisar criterios vinculantes.',por:'Orienta o vincula decisiones conforme a reglas de formación, publicación y aplicación.',cuida:'Verificar órgano emisor, registro, vigencia, obligatoriedad, precedente, contradicción o sustitución.'},
{t:'Precedente judicial',d:'Decisión anterior que puede tener relevancia interpretativa y, bajo reglas específicas, fuerza vinculante.',cuando:'Al argumentar que un tribunal debe seguir o considerar un criterio previo.',por:'Aporta consistencia interpretativa.',cuida:'Distinguir precedente obligatorio, tesis aislada, jurisprudencia y razonamiento persuasivo; comprobar aplicabilidad fáctica.'},
{t:'Tesis aislada',d:'Criterio publicado que no tiene por ese solo hecho la misma obligatoriedad que la jurisprudencia, conforme al sistema aplicable.',cuando:'Como apoyo interpretativo o persuasivo.',por:'Puede aportar razonamiento útil aunque su fuerza jurídica sea distinta.',cuida:'Comprobar registro, época, órgano, vigencia y si existe criterio obligatorio posterior.'},
{t:'Contradicción de criterios',d:'Mecanismo previsto para resolver divergencias entre criterios judiciales en los supuestos del sistema correspondiente.',cuando:'Cuando existen criterios incompatibles cuya unificación procede conforme a la ley.',por:'Busca uniformidad y certeza en la interpretación.',cuida:'Verificar legitimación, órgano competente, reglas temporales y resultado del procedimiento.'},
{t:'Suplencia de la queja',d:'Facultad u obligación legal de corregir deficiencias argumentativas en supuestos determinados, especialmente en ciertos medios de control.',cuando:'Cuando la materia y calidad de la persona promovente encuadran en una regla de suplencia.',por:'Evita que determinados defectos técnicos impidan protección en casos previstos.',cuida:'No es universal; identificar supuesto legal, alcance y límites.'},
{t:'Interés superior de la niñez',d:'Principio que exige considerar de manera primordial los derechos y necesidades de niñas, niños y adolescentes en decisiones que les afecten.',cuando:'En asuntos familiares, administrativos, penales u otros que involucren a personas menores de edad.',por:'Orienta decisiones hacia la protección integral de sus derechos.',cuida:'Debe concretarse en hechos, derechos involucrados y evaluación individual; no es una fórmula automática para favorecer una postura sin análisis.'},
{t:'Perspectiva de género',d:'Método de análisis que identifica desigualdades, estereotipos y posibles impactos diferenciados relevantes para resolver conforme a derechos y normas aplicables.',cuando:'Cuando los hechos o el contexto revelan posibles desigualdades o violencia basadas en género, y en los supuestos jurídicos correspondientes.',por:'Ayuda a evitar decisiones basadas en estereotipos y a examinar el contexto.',cuida:'Aplicarla con hechos y metodología, sin sustituir prueba ni prejuzgar automáticamente el resultado.'},
{t:'Reparación integral',d:'Conjunto de medidas para atender las consecuencias de una violación de derechos, en los regímenes que la reconocen.',cuando:'Cuando existe una violación o daño que legalmente da lugar a reparación.',por:'Busca restituir, compensar o atender consecuencias conforme al marco aplicable.',cuida:'Las medidas y requisitos varían; distinguir reparación civil, administrativa, penal y de derechos humanos.'}
,{t:'Audiencia',d:'Acto procesal en el que la autoridad escucha a las partes, recibe o desahoga actuaciones y/o adopta decisiones conforme a la naturaleza del procedimiento.',cuando:'Cuando el código o la resolución judicial fija una audiencia, o cuando una etapa oral requiere comparecencia.',por:'Permite ejercer contradicción, presentar argumentos y producir actuaciones en presencia de la autoridad, según el modelo procesal.',cuida:'Verifica objeto de la audiencia, comparecientes, representación, citación, pruebas autorizadas, orden de intervención y consecuencias de inasistencia.',requisitos:'Revisa citatorio y resolución que la señaló; prepara expediente, teoría del caso, documentos, testigos o peritos y peticiones concretas.',pasos:'1) Confirmar fecha, hora y modalidad. 2) Revisar qué se resolverá. 3) Preparar intervenciones y pruebas. 4) Registrar acuerdos, cargas y plazos que resulten.',consecuencias:'La inasistencia o falta de preparación puede producir consecuencias previstas en la ley o en la resolución; nunca deben suponerse sin consultar el régimen aplicable.',ejemplo:'Antes de una audiencia preliminar, preparar los hechos controvertidos, las pruebas ofrecidas y las cuestiones que deban resolverse.'},
{t:'Audiencia inicial',d:'Audiencia de apertura del procedimiento en los sistemas que la contemplan; su contenido varía sustancialmente por materia.',cuando:'En los procedimientos que expresamente prevén esta etapa, por ejemplo dentro del sistema penal acusatorio o ciertos procesos orales.',por:'Puede concentrar control judicial, planteamientos iniciales y decisiones procesales propias de esa materia.',cuida:'No trasladar automáticamente el significado penal a materia civil o familiar. Identifica código, etapa y objeto exacto de la audiencia.',requisitos:'Citación válida, comparecencia de sujetos requeridos, defensa o representación cuando proceda y preparación de solicitudes.',ejemplo:'En materia penal, revisar la finalidad concreta de la audiencia y las actuaciones previstas por el CNPP; en otra materia, consultar su propio código.'},
{t:'Audiencia preliminar',d:'Audiencia previa al juicio o a una etapa decisoria en ciertos procedimientos, destinada a depurar cuestiones, organizar el debate o resolver admisibilidad probatoria, según el código.',cuando:'Cuando la vía aplicable incluye esa audiencia y se ha llegado a la etapa procesal correspondiente.',por:'Busca delimitar controversias y preparar la etapa de juicio o desahogo de pruebas.',cuida:'Confirma qué cuestiones pueden resolverse, si hay oportunidad de convenio, qué pruebas se depuran y qué acuerdos vinculan a las partes.',requisitos:'Llevar propuesta clara sobre hechos no controvertidos, acuerdos probatorios, pruebas, excepciones y cuestiones pendientes, conforme a la vía.',ejemplo:'Preparar una relación de hechos controvertidos y explicar la pertinencia de cada medio de prueba ofrecido.'},
{t:'Audiencia de juicio',d:'Etapa oral destinada a desahogar pruebas y formular alegatos para que el tribunal resuelva, conforme al procedimiento aplicable.',cuando:'Cuando concluyen las etapas previas y el órgano jurisdiccional señala la audiencia de juicio.',por:'Permite producir y controvertir prueba ante la autoridad que resolverá, bajo los principios del sistema correspondiente.',cuida:'Revisar orden de desahogo, citaciones, objeciones, interrogatorios, documentos, incidentes y reglas de registro.',requisitos:'Preparación de testigos y peritos, disponibilidad de documentos, preguntas vinculadas a hechos controvertidos y plan de alegatos.',ejemplo:'Organizar cada prueba por el hecho específico que pretende acreditar y anticipar objeciones previsibles.'},
{t:'Sentencia definitiva',d:'Resolución que decide el litigio principal o pone fin a la instancia en los términos definidos por el ordenamiento aplicable.',cuando:'Después de la etapa de decisión, cuando el asunto está en estado de resolución.',por:'Resuelve las pretensiones y defensas que corresponde decidir en esa instancia.',cuida:'Leer considerandos y puntos resolutivos; verificar congruencia, exhaustividad, condenas, absoluciones, costas, notificación y medio de impugnación.',requisitos:'Para analizarla, identifica pretensiones, excepciones, hechos probados, valoración probatoria, fundamentos y efectos decretados.',consecuencias:'Puede ser impugnable y no necesariamente queda firme al dictarse. La firmeza depende de recursos, plazos y reglas aplicables.',ejemplo:'Después de una sentencia definitiva, calcular el plazo de impugnación desde la notificación legalmente eficaz, no solo desde la fecha escrita en la resolución.'},
{t:'Sentencia interlocutoria',d:'Resolución que decide una cuestión incidental o una cuestión procesal que la ley clasifica como interlocutoria; la clasificación varía por ordenamiento.',cuando:'Cuando se tramita y resuelve un incidente u otra cuestión que requiera decisión separada.',por:'Resuelve una cuestión dentro del procedimiento sin que necesariamente decida la pretensión principal.',cuida:'Determina exactamente qué resolvió, si afecta la continuación del juicio, qué recurso procede y cuándo empieza el plazo.',requisitos:'Revisar la promoción incidental, contestación, pruebas, trámite, considerandos y puntos resolutivos.',consecuencias:'Puede quedar firme respecto de la cuestión decidida sin que ello signifique que la sentencia definitiva del juicio sea firme.',ejemplo:'No clasificar toda resolución intermedia como interlocutoria: verificar la terminología y efectos que establece el código aplicable.'},
{t:'Sentencia firme',d:'Sentencia que ya no puede ser modificada por los medios ordinarios de impugnación disponibles, por haberse agotado, vencido o no resultar procedentes, conforme al régimen aplicable.',cuando:'Al determinar si una resolución puede ejecutarse o si ya cerró la discusión ordinaria.',por:'Permite identificar estabilidad procesal y efectos jurídicos de la decisión.',cuida:'Verifica notificación, recursos procedentes, interposición o vencimiento de plazos y posibles reglas especiales; no basta que la sentencia diga “definitiva”.',requisitos:'Constancias de notificación y, cuando corresponda, certificación o declaración judicial de firmeza.',consecuencias:'La firmeza puede permitir ejecución o producir cosa juzgada en los términos legales, pero esos efectos deben analizarse por separado.',ejemplo:'Antes de pedir ejecución, comprobar que la resolución condenatoria sea exigible y que se cumplan los requisitos de la vía.'},
{t:'Sentencia ejecutoriada',d:'Expresión usada para referirse a una sentencia que ha adquirido firmeza o autoridad ejecutoria según el ordenamiento y la práctica aplicables.',cuando:'Al acreditar que la resolución ya no admite impugnación ordinaria o que se actualizó la condición legal para su ejecución.',por:'Sirve para establecer la estabilidad de la decisión y sustentar actuaciones posteriores cuando la ley lo requiere.',cuida:'No asumir que “firme” y “ejecutoriada” son intercambiables en todos los códigos; consulta la definición legal, declaración y constancias del expediente.',requisitos:'Revisar régimen de ejecutoria, notificaciones, recursos y certificaciones emitidas por el órgano judicial.',consecuencias:'Puede habilitar ejecución, inscripción o cumplimiento, sujeto a la naturaleza de la condena y a los requisitos correspondientes.',ejemplo:'Solicitar que se certifique la ejecutoria cuando la legislación o el juzgado lo requiera, sin confundir esa certificación con el contenido de la sentencia.'},
{t:'Sentencia condenatoria',d:'Resolución que impone a una parte una prestación, obligación, sanción o consecuencia jurídica conforme a la materia.',cuando:'Cuando el órgano jurisdiccional considera procedente la pretensión o se acreditan los presupuestos legales para imponer la consecuencia.',por:'Define la conducta o prestación que debe cumplirse y los límites de la condena.',cuida:'Revisa sujeto obligado, prestación, cantidad, intereses, plazo, costas, condiciones y puntos resolutivos.',ejemplo:'En una condena al pago, verificar monto líquido, bases para liquidación, intereses y requisitos de ejecución.'},
{t:'Sentencia absolutoria',d:'Resolución que libera a la parte demandada o persona acusada de una pretensión, imputación o consecuencia en el alcance que establezca el fallo.',cuando:'Cuando el órgano jurisdiccional concluye que no procede imponer la condena o responsabilidad reclamada.',por:'Define que la pretensión no prospera total o parcialmente o que no se acreditó responsabilidad conforme al estándar aplicable.',cuida:'Analiza si la absolución es total o parcial, sus fundamentos, efectos, recursos y alcance frente a cada prestación o acusación.',ejemplo:'No inferir que la absolución respecto de una prestación resuelve automáticamente todas las demás si el fallo las trata separadamente.'},
{t:'Vista',d:'Acto por el que se pone una promoción, documento, prueba o cuestión en conocimiento de una parte o autoridad para que se pronuncie, cuando así lo ordena la ley o el tribunal.',cuando:'Al recibir una resolución que ordena dar vista y señala o implica una oportunidad para manifestarse.',por:'Permite contradicción y que la autoridad conozca la posición de la persona interesada.',cuida:'Identifica qué documentos se ponen a la vista, quién debe responder, plazo, forma de cómputo y consecuencia prevista.',ejemplo:'Contestar de manera puntual la cuestión sometida a vista y conservar constancia de presentación.'},
{t:'Traslado',d:'Comunicación procesal de un escrito o actuación a la contraparte para que conozca su contenido y actúe en los términos previstos.',cuando:'Cuando se corre traslado de demanda, contestación, incidente, recurso u otra promoción.',por:'Garantiza conocimiento y oportunidad de defensa o respuesta.',cuida:'Revisar qué se entregó, anexos, fecha y modalidad de notificación y plazo aplicable; “traslado” no siempre significa que exista el mismo número de días.',ejemplo:'Al recibir traslado de un incidente, identificar hechos, peticiones y pruebas que requieren respuesta.'},
{t:'Requerimiento judicial',d:'Mandato formal de la autoridad para que una persona haga, entregue, pague, se abstenga o cumpla una conducta dentro de los términos legales.',cuando:'Cuando la resolución ordena una conducta concreta y la ley habilita el requerimiento.',por:'Busca obtener cumplimiento y dejar constancia de la orden y de su comunicación.',cuida:'Precisar obligación, destinatario, plazo, apercibimiento, forma de notificación y posibilidad legal de cumplimiento.',consecuencias:'El incumplimiento puede activar medidas o consecuencias solo si están legalmente previstas y se cumplen sus presupuestos.',ejemplo:'Antes de afirmar incumplimiento, revisar que el requerimiento haya sido comunicado válidamente y que el plazo haya vencido.'},
{t:'Apercibimiento',d:'Advertencia formal de una consecuencia procesal o medida que puede imponerse si no se cumple una orden, cuando existe fundamento legal.',cuando:'Cuando la autoridad previene sobre una conducta exigida y anuncia una consecuencia para el incumplimiento.',por:'Hace saber el riesgo jurídico de no atender una determinación.',cuida:'Comprueba que la consecuencia esté prevista, sea clara, proceda en el caso y que la notificación sea eficaz.',ejemplo:'Transcribir con precisión el apercibimiento al valorar el incumplimiento; no presumir que cualquier advertencia autoriza cualquier sanción.'},
{t:'Desechamiento',d:'Determinación por la que la autoridad no admite una demanda, promoción, prueba o recurso por una causa prevista en la norma.',cuando:'Cuando se actualiza un defecto o impedimento legal que justifica no admitir la actuación.',por:'Evita tramitar actos que no cumplen los requisitos de procedencia.',cuida:'Distingue desechamiento, prevención, improcedencia y sobreseimiento; revisa motivación, oportunidad de subsanar y medio de impugnación.',ejemplo:'Si se desecha una demanda, identificar la causa exacta y el recurso o nueva presentación que legalmente pudiera proceder.'},
{t:'Sobreseimiento',d:'Resolución que termina un procedimiento sin resolver necesariamente el fondo de la pretensión, por una causa legal de terminación.',cuando:'Cuando se actualiza una causal de sobreseimiento prevista para esa vía o materia.',por:'Pone fin al procedimiento por un obstáculo o circunstancia legal distinta de una decisión de fondo, según el caso.',cuida:'Identifica causal, momento procesal, efectos sobre una nueva acción, costas, medidas cautelares y medios de impugnación.',ejemplo:'No equiparar sobreseimiento con absolución o sentencia que declara infundada la pretensión.'},
{t:'Rebeldía',d:'Situación procesal atribuida a quien no realiza un acto dentro del plazo o no comparece, con los efectos que establezca la ley.',cuando:'Cuando vence una oportunidad procesal y la autoridad declara o reconoce la consecuencia correspondiente.',por:'Permite que el procedimiento continúe pese a la falta de actuación de una parte, en los términos legales.',cuida:'Revisar validez del emplazamiento o notificación, plazo, efectos concretos y excepciones; la rebeldía no equivale automáticamente a admitir todos los hechos.',ejemplo:'Antes de atribuir consecuencias a la falta de contestación, confirmar el emplazamiento y la regla específica de la vía.'},
{t:'Deserción del recurso',d:'Consecuencia procesal que puede producirse cuando quien interpuso un recurso no cumple una carga requerida para su trámite, si la ley lo prevé.',cuando:'Al incumplirse una carga esencial del recurso en un régimen que contemple la deserción.',por:'Permite cerrar la impugnación que no cumple los requisitos procesales exigidos.',cuida:'Verifica si el código utiliza esta figura, qué carga faltó, si hubo requerimiento válido y qué medio de defensa existe.',ejemplo:'No usar “deserción” como sinónimo general de improcedencia; fundamentar la causa exacta.'},
{t:'Liquidación de sentencia',d:'Determinación cuantitativa de una condena cuando la resolución fijó bases pero no dejó totalmente determinado el monto.',cuando:'Cuando se requiere calcular cantidades, intereses, frutos, daños u otros conceptos conforme al fallo.',por:'Convierte las bases de la condena en una cantidad exigible, siguiendo el procedimiento aplicable.',cuida:'Respetar puntos resolutivos, periodos, tasas, operaciones, documentos soporte y posibilidad de objeción.',ejemplo:'Acompañar una planilla reproducible que explique cada concepto, periodo y operación, sin agregar prestaciones no concedidas.'},
{t:'Ejecución de sentencia',d:'Etapa o procedimiento destinado a hacer efectivo lo resuelto cuando existe título ejecutable y se cumplen los requisitos legales.',cuando:'Ante incumplimiento de una resolución susceptible de ejecución.',por:'Busca materializar la tutela reconocida judicialmente.',cuida:'Comprobar firmeza o ejecutabilidad, legitimación, obligación exigible, liquidación, plazos y medidas autorizadas.',ejemplo:'Separar la solicitud de ejecución de una petición de liquidación cuando el monto aún requiere determinación.'},
{t:'Cosa juzgada formal',d:'Estabilidad de una resolución dentro del procedimiento en que se dicta, en los términos reconocidos por el régimen aplicable.',cuando:'Al analizar si una cuestión ya no puede discutirse dentro del mismo proceso por la vía ordinaria.',por:'Ordena la continuidad procesal y evita reabrir cuestiones definitivamente resueltas en esa instancia.',cuida:'Distinguirla de la cosa juzgada material y verificar recursos, excepciones y alcance de la resolución.',ejemplo:'Una determinación puede ser inimpugnable dentro de una etapa sin resolver con efectos generales la pretensión sustantiva.'},
{t:'Cosa juzgada material',d:'Efecto que impide volver a litigar una controversia ya resuelta de manera firme cuando se reúnen los requisitos legales.',cuando:'Al valorar si una nueva demanda reproduce una controversia decidida.',por:'Protege estabilidad de las decisiones y seguridad jurídica.',cuida:'Analiza identidad de partes, objeto y causa, alcance de los puntos resolutivos y excepciones reconocidas por el régimen.',ejemplo:'Comparar demanda previa, sentencia firme y nueva pretensión antes de afirmar que existe cosa juzgada.'},
{t:'Prueba superveniente',d:'Medio probatorio que surge o se conoce después de la oportunidad ordinaria, cuya admisión depende de los supuestos y requisitos legales.',cuando:'Cuando aparece un documento o elemento probatorio posterior o desconocido oportunamente por causa justificable.',por:'Puede permitir que se valore evidencia relevante pese a la etapa procesal, si el régimen lo autoriza.',cuida:'Explica cuándo surgió o se conoció, por qué no se ofreció antes, su pertinencia y la regla específica de admisión.',ejemplo:'Acompañar la prueba con una explicación documentada de su carácter superveniente y solicitar su admisión conforme al código.'},
{t:'Objeción de prueba',d:'Planteamiento mediante el cual una parte cuestiona admisibilidad, autenticidad, alcance o forma de producción de un medio probatorio, según el momento y reglas aplicables.',cuando:'En la oportunidad procesal prevista para objetar documentos, preguntas, peritajes u otros medios.',por:'Busca evitar que una prueba irregular o improcedente sea admitida o valorada indebidamente.',cuida:'Precisar si se cuestiona autenticidad, pertinencia, legalidad, metodología o valor; cada objeción tiene requisitos distintos.',ejemplo:'No confundir objetar autenticidad de un documento con controvertir el peso probatorio de su contenido.'},
{t:'Prueba ilícita',d:'Elemento probatorio obtenido o incorporado con vulneración de derechos o reglas cuya infracción produce consecuencias de exclusión o invalidez conforme al régimen aplicable.',cuando:'Al identificar una vulneración relevante en obtención o incorporación de evidencia.',por:'Protege derechos y la integridad del proceso probatorio.',cuida:'Identifica derecho afectado, forma de obtención, vínculo con la prueba y regla de exclusión aplicable; no toda irregularidad tiene idéntico efecto.',ejemplo:'Explicar la conducta concreta que produjo la prueba y la consecuencia jurídica solicitada.'},
{t:'Hecho notorio',d:'Hecho generalmente conocido o cuya certeza puede establecerse sin prueba ordinaria, conforme a los límites legales y jurisprudenciales.',cuando:'Cuando una parte sostiene que un hecho no requiere prueba por su notoriedad jurídicamente reconocible.',por:'Evita exigir prueba innecesaria sobre hechos que reúnen el estándar aplicable.',cuida:'La notoriedad no es lo mismo que una afirmación difundida; explica alcance, contexto, fecha y criterio jurídico pertinente.',ejemplo:'Identificar el hecho preciso y por qué cumple los requisitos para ser considerado notorio.'},
{t:'Carga procesal',d:'Conducta que una parte debe realizar en su propio interés procesal para evitar una consecuencia desfavorable, sin ser necesariamente una obligación exigible por la contraparte.',cuando:'Al identificar qué actuación corresponde a cada parte y en qué momento.',por:'Permite gestionar oportunidades, prueba, impugnaciones y cumplimiento de requisitos.',cuida:'Distingue carga, deber y obligación; verifica plazo y consecuencia específica de omitir la conducta.',ejemplo:'Ofrecer prueba dentro de la etapa legal es una carga procesal cuyo incumplimiento puede impedir su admisión.'},
{t:'Legitimación procesal',d:'Aptitud reconocida por el ordenamiento para intervenir en un proceso como parte respecto de una relación o pretensión.',cuando:'Al preparar demanda, contestación, incidente o recurso y verificar quién puede promover.',por:'Vincula a la persona que comparece con la posición procesal discutida.',cuida:'Distingue legitimación en la causa y en el proceso, personalidad y representación; no son conceptos idénticos.',ejemplo:'Acreditar la calidad en que se promueve y anexar el documento requerido para esa representación.'},
{t:'Personalidad',d:'Aptitud y acreditación con que una persona comparece en juicio por derecho propio o en representación de otra, según el uso procesal aplicable.',cuando:'Al presentar un escrito o cuando se cuestiona la representación de quien comparece.',por:'Permite verificar que el acto proviene de quien puede realizarlo procesalmente.',cuida:'Revisar poder, nombramiento, facultades, vigencia y requisitos del código; personalidad no equivale a legitimación sustantiva.',ejemplo:'Adjuntar el instrumento de representación y precisar el carácter con que se actúa.'},
{t:'Prueba pericial',d:'Medio de prueba que incorpora conocimientos especializados mediante una persona experta, conforme a las reglas de la materia.',cuando:'Cuando un hecho controvertido requiere conocimientos científicos, técnicos, artísticos o especializados.',por:'Ayuda a explicar cuestiones que exceden el conocimiento ordinario del tribunal.',cuida:'Definir puntos periciales, especialidad, metodología, documentos base, contradicción y requisitos de designación.',ejemplo:'Formular preguntas periciales conectadas con hechos litigiosos, evitando pedir al perito que decida cuestiones jurídicas reservadas al tribunal.'},
{t:'Prueba testimonial',d:'Declaración de una persona sobre hechos que conoce y que son relevantes para el litigio, recibida conforme a reglas procesales.',cuando:'Cuando un testigo puede aportar conocimiento directo o relevante sobre hechos controvertidos.',por:'Permite introducir información fáctica a través de interrogatorio y contradicción.',cuida:'Identificar qué hecho conoce, cómo lo conoció, citación, interrogatorio, objeciones y valoración de credibilidad.',ejemplo:'Preparar preguntas abiertas sobre hechos observados, sin sugerir respuestas ni confundir preparación con aleccionamiento.'}

];

export const DICCIONARIO_JURIDICO = [
{t:'Acción',d:'Facultad de acudir a la jurisdicción para plantear una pretensión y solicitar tutela judicial.',alcance:'No garantiza que la pretensión sea fundada; deben satisfacerse los requisitos de procedencia y fondo.'},
{t:'Pretensión',d:'Petición concreta de tutela que una persona formula frente a otra ante una autoridad o por una vía jurídicamente prevista.',alcance:'Debe distinguirse de los hechos que la sustentan y de la acción o vía procesal utilizada.'},
{t:'Derecho subjetivo',d:'Facultad o posición jurídica atribuida a una persona por el ordenamiento.',alcance:'Su existencia, límites y forma de exigibilidad dependen de la norma aplicable.'},
{t:'Obligación',d:'Relación jurídica que puede imponer a una persona el deber de dar, hacer o no hacer algo frente a otra.',alcance:'En cada caso deben identificarse fuente, sujetos, objeto, exigibilidad y posibles causas de extinción.'},
{t:'Responsabilidad civil',d:'Deber de reparar consecuencias dañosas cuando concurren los elementos y presupuestos exigidos por la ley.',alcance:'Los requisitos varían según sea contractual, extracontractual u otra modalidad.'},
{t:'Daño',d:'Lesión o menoscabo jurídicamente relevante en una persona, bienes o intereses protegidos.',alcance:'La existencia, causalidad, prueba y reparación deben examinarse conforme al régimen aplicable.'},
{t:'Nulidad',d:'Consecuencia jurídica que priva total o parcialmente de efectos a un acto por un defecto reconocido por el ordenamiento.',alcance:'No todo defecto genera nulidad automática; importan tipo de acto, norma, oportunidad y efectos.'},
{t:'Buena fe',d:'Estándar jurídico de conducta leal y honesta cuyo contenido depende de la institución y la norma aplicable.',alcance:'No es una fórmula que sustituya la prueba ni opera de idéntica manera en todas las materias.'},
{t:'Debido proceso',d:'Conjunto de garantías aplicables a procedimientos para proteger defensa, audiencia y otras exigencias constitucionales y legales.',alcance:'Su contenido concreto depende de la materia, la autoridad y el tipo de procedimiento.'},
{t:'Legalidad',d:'Exigencia de que los actos de autoridad y las conductas reguladas se ajusten al marco jurídico que corresponda.',alcance:'En materia penal, administrativa y constitucional tiene manifestaciones específicas.'},
{t:'Seguridad jurídica',d:'Exigencia de previsibilidad, certeza y actuación conforme a reglas jurídicas reconocibles.',alcance:'Se analiza junto con las garantías y normas concretas invocadas.'},
{t:'Igualdad procesal',d:'Exigencia de oportunidades procesales equilibradas conforme a la ley, sin desconocer diferencias legítimas del procedimiento.',alcance:'No implica que toda parte deba recibir idéntico trato en circunstancias jurídicamente distintas.'},
{t:'Contradicción',d:'Posibilidad de conocer y controvertir argumentos y pruebas en los términos que establezca el procedimiento.',alcance:'Su alcance depende de la etapa, la materia y las reglas de admisión y desahogo.'},
{t:'Carga de la prueba',d:'Regla que determina quién soporta el riesgo procesal de no acreditar determinados hechos.',alcance:'No equivale siempre a quién debe aportar material probatorio; hay presunciones y reglas especiales.'},
{t:'Presunción',d:'Inferencia que el ordenamiento o el razonamiento permite obtener de un hecho conocido a otro desconocido.',alcance:'Distinguir presunciones legales y humanas, así como las que admiten prueba en contrario.'},
{t:'Cosa juzgada',d:'Efecto de estabilidad y vinculación de una decisión judicial cuando se cumplen los requisitos legales.',alcance:'Revisar identidad de partes, objeto y causa u otros requisitos propios del régimen correspondiente.'},
{t:'Tutela judicial efectiva',d:'Derecho a acceder a una justicia que tramite y resuelva conforme a las garantías aplicables y permita la efectividad de las decisiones.',alcance:'No significa obtener necesariamente una sentencia favorable.'},
{t:'Proporcionalidad',d:'Método de análisis jurídico que examina la relación entre una medida, su finalidad y las restricciones o afectaciones que produce.',alcance:'Los pasos y el estándar varían según el contexto constitucional o legal.'},
{t:'Principio pro persona',d:'Criterio constitucional de interpretación en materia de derechos humanos que favorece la protección más amplia dentro del marco jurídico aplicable.',alcance:'No autoriza a ignorar competencias, reglas constitucionales ni criterios jurídicos pertinentes.'},
{t:'Supremacía constitucional',d:'Principio por el que la Constitución ocupa la posición superior en el orden jurídico nacional conforme al propio sistema constitucional.',alcance:'Su aplicación concreta requiere atender al texto constitucional, tratados y criterios jurisdiccionales aplicables.'},
{t:'Reserva de ley',d:'Exigencia de que ciertas materias sean reguladas mediante ley formal, en los términos que determina la Constitución.',alcance:'El ámbito reservado depende de la materia y de la disposición constitucional correspondiente.'},
{t:'Irretroactividad',d:'Regla constitucional y legal que limita la aplicación retroactiva de normas en perjuicio, conforme al contexto jurídico aplicable.',alcance:'Analizar fecha de hechos, vigencia, derechos, normas transitorias y criterios aplicables.'},
{t:'Jerarquía normativa',d:'Relación de superioridad y subordinación entre normas conforme al sistema jurídico.',alcance:'La solución de conflictos normativos también puede depender de competencia, especialidad, temporalidad y reglas constitucionales.'},
{t:'Interpretación sistemática',d:'Lectura de una disposición en relación con otras normas y con la estructura del ordenamiento.',alcance:'Debe exponerse cómo las normas relacionadas apoyan la interpretación propuesta.'},
{t:'Analogía',d:'Razonamiento que aplica a un supuesto no regulado una solución prevista para otro semejante cuando jurídicamente es admisible.',alcance:'Tiene límites importantes, especialmente en materia penal y en ámbitos sujetos a reserva legal.'},
{t:'Principio de congruencia',d:'Exigencia de correspondencia entre lo pedido, lo debatido y lo resuelto, de acuerdo con las reglas procesales.',alcance:'Puede analizarse en relación con pretensiones, excepciones, agravios y puntos resolutivos.'},
{t:'Exhaustividad',d:'Deber de atender los puntos que legalmente deben resolverse y que fueron planteados en el debate.',alcance:'No obliga a responder argumentos irrelevantes o ajenos a la controversia en los mismos términos.'},
{t:'Interés jurídico',d:'Afectación o relación jurídica concreta que permite a una persona reclamar tutela en los supuestos exigidos por la norma.',alcance:'No debe confundirse automáticamente con interés legítimo ni con legitimación.'},
{t:'Interés legítimo',d:'Posición especial frente al orden jurídico cuya afectación puede permitir acceso a una vía de tutela en los términos constitucionales y legales.',alcance:'Sus requisitos varían por materia; en amparo debe estudiarse conforme a la Constitución y la Ley de Amparo.'},
{t:'Orden público',d:'Conjunto de reglas o intereses que el ordenamiento considera de observancia necesaria en un ámbito determinado.',alcance:'No basta invocar la expresión; hay que identificar la norma y explicar su efecto en el caso.'},
{t:'Principio de legalidad penal',d:'Exigencia de que delitos y penas tengan base legal previa y suficientemente determinada.',alcance:'Se vincula con garantías específicas y no debe ampliarse por analogía en perjuicio de la persona imputada.'},
{t:'Presunción de inocencia',d:'Garantía que exige tratar como inocente a la persona imputada mientras no se establezca responsabilidad mediante el procedimiento legal.',alcance:'Comprende dimensiones de trato, prueba y decisión, según el marco constitucional y procesal.'},
{t:'Autonomía de la voluntad',d:'Espacio reconocido por el Derecho para que las personas regulen sus relaciones mediante actos jurídicos dentro de los límites legales.',alcance:'Tiene límites por normas imperativas, orden público, derechos de terceros y protección de personas.'},
{t:'Pacta sunt servanda',d:'Expresión latina que indica que los pactos válidamente celebrados deben cumplirse.',alcance:'El cumplimiento contractual está sujeto a requisitos, interpretación, excepciones y límites legales.'},
{t:'Lex specialis',d:'Regla interpretativa según la cual la disposición especial puede prevalecer sobre la general en el supuesto regulado.',alcance:'Debe comprobarse que ambas normas regulen el caso y que no exista regla superior o transitoria que cambie el análisis.'}
,{t:'Jurisdicción',d:'Potestad estatal de resolver controversias y ejercer funciones jurisdiccionales conforme a la Constitución y las leyes.',alcance:'Debe distinguirse de competencia: la jurisdicción es la potestad y la competencia distribuye su ejercicio. Revisa materia, territorio, grado y reglas especiales.',cuando:'Al determinar qué órgano puede conocer de la controversia.',por:'Define el marco de autoridad que puede impartir justicia en el asunto.',cuida:'No basta nombrar un juzgado; justifica la competencia con los datos relevantes del caso.'},
{t:'Competencia',d:'Atribución legal que determina qué órgano jurisdiccional debe conocer un asunto por materia, territorio, grado, cuantía u otros criterios.',alcance:'Los criterios y la posibilidad de prórroga o impugnación dependen de la materia y del ordenamiento.',cuando:'Antes de presentar demanda y al revisar excepciones o declinatorias.',por:'Evita promover ante un órgano que no debe conocer del asunto.',cuida:'Verifica domicilio, lugar de cumplimiento, cuantía, materia, turno y reglas especiales.'},
{t:'Vía procesal',d:'Procedimiento legal por el que debe tramitarse una pretensión.',alcance:'La vía incorrecta puede generar prevención, improcedencia, reconducción u otra consecuencia prevista; no se presume que toda vía sea intercambiable.',cuando:'Al definir la estrategia y redactar demanda.',por:'Establece etapas, plazos, requisitos y medios de defensa.',cuida:'Identifica norma habilitante, pretensión, cuantía y procedimiento aplicable.'},
{t:'Acción y pretensión: diferencia',d:'La acción alude al acceso a la jurisdicción; la pretensión es la tutela concreta que se pide.',alcance:'La terminología doctrinal puede variar; en práctica conviene identificar por separado la vía, el derecho invocado y la petición exacta.',cuando:'Al estructurar demanda o analizar excepciones.',por:'Evita confundir el derecho a pedir tutela con que la petición sea fundada.',cuida:'Especifica qué declaración, condena, constitución o medida se solicita.'},
{t:'Legitimación activa',d:'Vinculación jurídicamente reconocida de quien demanda con la pretensión que hace valer.',alcance:'Debe diferenciarse de personalidad y de la existencia final del derecho; los requisitos dependen de la acción y materia.',cuando:'Al identificar quién debe promover.',por:'Sustenta que la persona actora está habilitada para reclamar esa tutela.',cuida:'Acredita titularidad, calidad, sucesión, representación o interés conforme a la norma.'},
{t:'Legitimación pasiva',d:'Vinculación de la persona demandada con la relación jurídica o conducta frente a la que se pide tutela.',alcance:'No equivale simplemente a ser mencionado en los hechos; debe existir relación con la pretensión según el derecho aplicable.',cuando:'Al determinar contra quién dirigir la demanda.',por:'Evita reclamar a quien no debe responder jurídicamente por la pretensión.',cuida:'Relaciona cada prestación con la persona demandada y su papel jurídico.'},
{t:'Personalidad y representación',d:'La personalidad se refiere a la comparecencia procesal reconocida; la representación es la actuación por cuenta de otra persona conforme a un título válido.',alcance:'Los códigos pueden emplear términos específicos; revisa poderes, nombramientos, tutela, mandato o representación orgánica.',cuando:'Al comparecer por una persona física, moral o representada.',por:'Acredita que quien firma puede actuar en ese carácter.',cuida:'Revisa facultades expresas, vigencia, formalidades y límites.'},
{t:'Fundamentación y motivación',d:'La fundamentación identifica las normas que sustentan una decisión; la motivación expone los hechos y razones que conectan esas normas con el caso.',alcance:'Su exigencia concreta depende del acto y autoridad, con bases constitucionales y legales aplicables.',cuando:'Al redactar argumentos contra un acto de autoridad o revisar una resolución.',por:'Permite entender y controvertir la razón jurídica y fáctica de una decisión.',cuida:'Señala norma omitida o mal aplicada y explica por qué los hechos no justifican la conclusión.'},
{t:'Congruencia externa e interna',d:'La congruencia externa compara lo resuelto con lo pedido y debatido; la interna exige que la propia resolución no contenga contradicciones relevantes.',alcance:'La formulación y consecuencias se desarrollan en normas y criterios aplicables.',cuando:'Al revisar una sentencia o preparar agravios.',por:'Permite identificar omisiones, exceso decisorio o contradicciones.',cuida:'Cita la prestación o argumento, el punto resolutivo y la discrepancia específica.'},
{t:'Exhaustividad de la sentencia',d:'Exigencia de resolver los puntos que legalmente deben ser examinados y que integran la controversia.',alcance:'No obliga a reproducir cada frase de las partes; importa que se atiendan los temas decisivos.',cuando:'Al auditar una sentencia para detectar omisiones.',por:'Permite identificar si una pretensión, excepción o argumento esencial quedó sin respuesta.',cuida:'Haz una matriz de prestaciones, excepciones, pruebas y puntos resolutivos.'},
{t:'Principio dispositivo',d:'Regla procesal según la cual las partes tienen iniciativa relevante en la delimitación de pretensiones y aportación de hechos, en el alcance de cada sistema.',alcance:'No opera de igual modo en todas las materias; puede coexistir con facultades oficiosas de la autoridad.',cuando:'Al decidir qué debe alegarse, pedirse y probarse.',por:'Ayuda a entender la distribución de iniciativa y cargas procesales.',cuida:'Identifica las facultades oficiosas y reglas protectoras específicas del procedimiento.'},
{t:'Principio de oralidad',d:'Organización procesal que privilegia actuaciones orales en audiencias, en los términos establecidos por la ley.',alcance:'No elimina escritos, registros ni formalidades; su alcance depende del procedimiento.',cuando:'Al preparar intervención en un proceso oral.',por:'Favorece inmediación, concentración y debate en los supuestos previstos.',cuida:'Revisa qué peticiones deben formularse oralmente y cuáles requieren presentación escrita.'},
{t:'Inmediación',d:'Principio por el que la autoridad que dirige o decide debe tener contacto directo con las actuaciones probatorias en los términos del sistema aplicable.',alcance:'Su alcance depende de la materia, la forma de desahogo y las excepciones legales.',cuando:'Al evaluar producción de prueba y conducción de audiencias.',por:'Contribuye a que la decisión se base en el material recibido conforme al procedimiento.',cuida:'Verifica quién recibió la prueba y qué reglas regulan registros, sustituciones o excepciones.'},
{t:'Concentración procesal',d:'Orientación a reunir actos procesales en el menor número razonable de actuaciones o audiencias cuando la ley lo dispone.',alcance:'No autoriza omitir garantías, plazos ni oportunidades de defensa.',cuando:'Al preparar audiencias y organizar el debate.',por:'Busca eficiencia sin sacrificar contradicción y debido proceso.',cuida:'Agrupa temas y pruebas, pero confirma que cada acto se realice con las formalidades necesarias.'},
{t:'Buena fe procesal',d:'Estándar de conducta leal en el proceso, cuyo contenido y consecuencias dependen de las normas aplicables.',alcance:'No sustituye una causal legal ni permite presumir mala fe sin hechos concretos.',cuando:'Al analizar conductas procesales, abuso o deberes de colaboración.',por:'Orienta el ejercicio responsable de facultades procesales.',cuida:'Describe conducta, norma, perjuicio y consecuencia solicitada; evita usarla como descalificación retórica.'}

];

