// Evita fichas repetidas: si una ampliación tiene el mismo título, conserva la versión más reciente y detallada.
function _bjpUnicos(lista) {
  const mapa = new Map();
  for (const item of lista) mapa.set(String(item.t || "").trim().toLocaleLowerCase("es-MX"), item);
  lista.splice(0, lista.length, ...mapa.values());
}
for (const lista of [TERMINOS_PROCESALES, DICCIONARIO_JURIDICO, LOCUCIONES_LATINAS]) _bjpUnicos(lista);

// Ampliación práctica V3: campos de trabajo forense; no sustituyen la verificación del ordenamiento aplicable.
const _bjpAmpliaciones = {
  'Promoción': {requisitos:'Expediente y órgano correctos; carácter de quien promueve; petición concreta; hechos mínimos necesarios; documentos anexos; firma y medio de presentación permitido.',pasos:'1) Lee la última resolución. 2) Define una petición por punto. 3) Vincula la solicitud con constancias del expediente. 4) Anexa documentos. 5) Conserva acuse y revisa el acuerdo posterior.',consecuencias:'Una petición ambigua, extemporánea o presentada sin requisitos puede no producir el efecto buscado; la consecuencia concreta depende de la ley y del acuerdo.',ejemplo:'“Se solicita se expidan copias certificadas de las actuaciones identificadas, previo pago de derechos si procede”, precisando expediente y finalidad.'},
  'Demanda': {requisitos:'Competencia y vía; identificación de partes; prestaciones; hechos claros y separados; fundamentos pertinentes; valor o cuantía cuando corresponda; pruebas; documentos base; domicilios; firmas y anexos exigidos.',pasos:'1) Diagnostica la acción. 2) Verifica legitimación activa y pasiva. 3) Formula prestaciones medibles. 4) Ordena hechos cronológicamente. 5) Asocia pruebas con hechos. 6) Audita anexos, plazo y competencia.',consecuencias:'Defectos pueden ocasionar prevención, desechamiento, incompetencia u otras consecuencias; no son automáticas y dependen del requisito omitido y la norma aplicable.',ejemplo:'Una matriz interna puede relacionar cada prestación con hechos, norma invocada y prueba ofrecida antes de presentar el escrito.'},
  'Prevención': {requisitos:'Resolución completa; fecha y forma de notificación; cada defecto señalado; plazo y regla de cómputo; posibilidad de subsanar; anexos necesarios.',pasos:'1) Copia cada punto requerido. 2) Responde en el mismo orden. 3) Corrige el escrito y acompaña anexos. 4) Verifica firma y presentación. 5) Guarda acuse y revisa el acuerdo.',consecuencias:'La falta de desahogo puede producir la consecuencia anunciada o prevista en la ley, pero debe verificarse la validez del requerimiento y el régimen aplicable.',ejemplo:'Usar una tabla de dos columnas: “requerimiento judicial” y “respuesta/documento que lo satisface”.'},
  'Sentencia': {requisitos:'Identifica órgano, fecha, partes, antecedentes, consideraciones, valoración de pruebas, fundamentos y puntos resolutivos.',pasos:'1) Resume qué pidió cada parte. 2) Localiza qué se tuvo por probado. 3) Compara razones y resolutivos. 4) Identifica omisiones o contradicciones. 5) Verifica notificación, impugnación y cumplimiento.',consecuencias:'La sentencia puede ser impugnable, firme o ejecutable según su tipo y las reglas aplicables; esas cualidades no son sinónimos.',ejemplo:'Preparar una tabla de pretensión, decisión, fundamento y efecto para detectar incongruencia u omisión.'},
  'Sentencia interlocutoria': {requisitos:'Identifica incidente o cuestión resuelta, trámite, pruebas, razonamiento, resolutivos y reglas de impugnación.',pasos:'1) Define la cuestión incidental. 2) Contrasta lo solicitado con lo resuelto. 3) Analiza motivación. 4) Determina recurso y plazo. 5) Evalúa efecto sobre el proceso principal.',consecuencias:'Puede resolver definitivamente una cuestión incidental, pero no necesariamente termina el juicio principal ni queda firme al dictarse.',ejemplo:'Distingue la fecha de la resolución de la fecha de notificación eficaz para calcular el plazo que corresponda.'},
  'Sentencia firme': {requisitos:'Resolución íntegra, constancias de notificación, recursos disponibles, constancia de interposición o vencimiento de plazos y declaración judicial si procede.',pasos:'1) Identifica recursos legales. 2) Verifica notificación. 3) Confirma si hubo impugnación. 4) Revisa resolución del recurso o vencimiento. 5) Obtén certificación cuando corresponda.',consecuencias:'Puede generar estabilidad procesal y habilitar actos posteriores; la ejecución requiere revisar además el tipo de condena y requisitos específicos.',ejemplo:'No afirmar firmeza solo porque la contraparte no compareció a una audiencia: revisar los medios de impugnación y las constancias.'},
  'Acción': {cuando:'Al decidir qué tutela judicial se pretende activar y si los hechos y la relación jurídica encuadran en una acción reconocida.',por:'Permite pedir que un órgano jurisdiccional conozca de una pretensión, pero no asegura su procedencia ni que se gane el juicio.',cuida:'Distingue acción, pretensión, derecho subjetivo, legitimación, vía y competencia; son preguntas relacionadas, pero diferentes.',requisitos:'Identifica fuente del derecho, sujetos, hechos constitutivos, prestación solicitada, plazo, defensas previsibles y requisitos de procedencia.',ej:'Antes de redactar, formula en una oración: quién reclama, contra quién, qué tutela solicita y qué hechos jurídicamente relevantes la sustentan.'},
  'Pretensión': {cuando:'Al definir la tutela específica que se pide: condena, declaración, constitución, restitución u otra que la vía permita.',por:'Delimita el resultado que se solicita al órgano jurisdiccional y ayuda a estructurar prestaciones y puntos resolutivos.',cuida:'Debe ser clara, posible y congruente con los hechos; no confundas la pretensión con el argumento jurídico que la apoya.',requisitos:'Especifica sujeto obligado, conducta o declaración pedida, objeto, alcance, cantidad o bases de liquidación si corresponde.',ej:'En vez de pedir genéricamente “se haga justicia”, identifica la condena, declaración o medida concreta que se solicita.'},
  'Competencia': {cuando:'Antes de presentar demanda, contestar o plantear una excepción sobre el órgano que debe conocer.',por:'Determina el órgano habilitado por ley para conocer el asunto.',cuida:'No confundir competencia con jurisdicción ni con turno. Revisa materia, territorio, grado, cuantía y reglas especiales.',requisitos:'Documenta domicilio, lugar de cumplimiento, naturaleza de la relación, cuantía y cláusulas relevantes, sin presumir que un solo factor decide todo.',ej:'Explica qué regla legal conecta los hechos del caso con el órgano ante el que se promueve.'},
  'Fundamentación y motivación': {cuando:'Al redactar un concepto de violación o agravio contra un acto o resolución, o al auditar la justificación de una autoridad.',por:'Permite evaluar si la decisión identifica base normativa y explica su aplicación a los hechos.',cuida:'Cita el fundamento que falta o se aplica incorrectamente y rebate las razones decisivas; no basta afirmar “carece de fundamentación”.',requisitos:'Identifica acto, norma aplicable, hechos relevantes, razonamiento de autoridad, defecto concreto y perjuicio.',ej:'Señala el párrafo de la resolución, la disposición omitida o mal interpretada y por qué el resultado habría de revisarse.'},
  'Lex specialis derogat legi generali': {uso:'Criterio interpretativo, no regla automática: puede orientar entre normas concurrentes cuando la especialidad, jerarquía, temporalidad y régimen transitorio lo permiten.',ej:'Explica cuál norma regula específicamente el supuesto, cuál es general, por qué ambas podrían concurrir y si existe una regla superior o transitoria que determine otra solución.'},
  'Iura novit curia': {uso:'Máxima sobre el conocimiento judicial del Derecho; no elimina las cargas de alegación y prueba de los hechos ni permite alterar arbitrariamente la pretensión o afectar la contradicción.',ej:'Aunque la parte cite una norma discutible, el análisis debe separar hechos alegados, pretensión y calificación jurídica posible, respetando congruencia y audiencia.'}
};
for (const lista of [TERMINOS_PROCESALES, DICCIONARIO_JURIDICO, LOCUCIONES_LATINAS]) {
  for (const item of lista) if (_bjpAmpliaciones[item.t]) Object.assign(item, _bjpAmpliaciones[item.t]);
}
